pub fn algebra_ref_is_grounded(algebra: Rc<Node>) -> bool {
    match (*algebra.kind.clone()).clone() {
    NodeKind::TypeNode { connective: c, .. } => match (*c.clone()).clone() {
    Connective::Atom { identity: _, .. } => match crate::v2_std_kind::kind_denoted_by_node(algebra.clone()) {
    Some(_) => true,
    std::option::Option::None => false,
},
    Connective::Conj => true,
    Connective::Disj => true,
    Connective::Arrow => true,
    Connective::Instantiation => true,
},
    NodeKind::ComputationNode { behavior: _, .. } => false,
}
}

