pub fn infer_descent_witness_for_node(n: Rc<Node>) -> Rc<Witness<Rc<TerminationProof>>> {
    match (*crate::v2_std_cardinality::termination_proof_witness_for_node(n)).clone() {
    Witness::Holds { value: proof, .. } => Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: proof.clone(),
}),
    Witness::Violates { diagnostic: upstream, .. } => Rc::new(Witness::<Rc<TerminationProof>>::Violates {
    diagnostic: infer_descent_not_derived_diagnostic(upstream.at.clone()),
}),
}
}

pub fn algebra_ref_from_grounding(grounding: Rc<CanonicalGrounding>) -> Rc<AlgebraRef> {
    Rc::new(AlgebraRef {
    algebra: grounding.witness.structural.evidence.clone(),
    witness: grounding.node.clone(),
})
}

pub fn canonical_grounding_admits_infer_facts(grounding: Rc<CanonicalGrounding>) -> bool {
    ((((crate::v2_std_node::well_formed(grounding.node.clone()) && crate::v2_std_node::well_formed(grounding.witness.structural.evidence.clone())) && (grounding.witness.structural.property.clone() == "constraint_property_being_canonical".to_string())) && (grounding.witness.closedness.property.clone() == "constraint_property_candidate_set_closedness".to_string())) && crate::v2_std_node::node_same_occurrence(grounding.witness.closedness.evidence.clone(), grounding.node.clone()))
}

pub fn inferred_facts_construction(grounding: Rc<CanonicalGrounding>, descent: Rc<Witness<Rc<TerminationProof>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    if canonical_grounding_admits_infer_facts(grounding.clone()) {
        Rc::new(Outcome::Accepted {
    value: Rc::new(InferredFacts {
    grounding: Rc::new(NodeGrounding::DerivedGrounding {
    grounding: grounding.clone(),
}),
    descent: descent.clone(),
    denotation: crate::std_optional::optional_absent(),
    type_instances: Rc::new(vec![]),
    refinement_carrier: crate::std_optional::optional_absent(),
}),
    diagnostics: Box::new(std::option::Option::None),
})
    } else {
        crate::v2_std_diagnostic::outcome_rejected(infer_canonical_grounding_incoherent_diagnostic(grounding.node.clone()))
    }
}

pub fn inferred_facts_from_grounding(grounding: Rc<CanonicalGrounding>, descent: Rc<Witness<Rc<TerminationProof>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    inferred_facts_construction(grounding, descent)
}

pub fn inferred_facts_not_derived(node: Rc<Node>, site: NotDerivedSite, descent: Rc<Witness<Rc<TerminationProof>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    Rc::new(Outcome::Accepted {
    value: Rc::new(InferredFacts {
    grounding: Rc::new(NodeGrounding::GroundingNotDerived {
    node: node.clone(),
    site: site.clone(),
}),
    descent: descent.clone(),
    denotation: crate::std_optional::optional_absent(),
    type_instances: Rc::new(vec![]),
    refinement_carrier: crate::std_optional::optional_absent(),
}),
    diagnostics: Box::new(Some(crate::v2_std_diagnostic::diagnostics_singleton(infer_grounding_not_derived_diagnostic(crate::v2_std_diagnostic::node_locus(node.clone()))))),
})
}

pub fn concat_inferred_facts_entries(a: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, b: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>> {
    crate::std_algebra::fold_list(crate::std_algebra::map_support_keys(b.clone()), a, |acc, key| match v1_rt::lookup(&b, key.clone()) {
    Some(xs) => crate::std_algebra::fold_list(xs.clone(), acc, |into, facts| inferred_facts_index_enter(into, Rc::new(InferredFactsEntry {
    node: key.clone(),
    facts: facts.clone(),
}))),
    std::option::Option::None => acc.clone(),
})
}

