pub fn infer_product_child_evidence_edges(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Option<Rc<Vec<Rc<Edge>>>> {
    infer_formation_child_evidence_edges(node.children.clone(), entries, |edge| (crate::v2_std_node::arrow_signature_order_edge(node.clone(), edge.clone()) || crate::v2_std_node::arrow_named_edge_is_metadata(edge.clone())))
}

pub fn infer_formation_child_evidence_edges(children: Rc<Vec<Rc<Edge>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, is_metadata: impl Fn(Rc<Edge>) -> bool + Clone) -> Option<Rc<Vec<Rc<Edge>>>> {
    children.iter().cloned().fold(crate::std_optional::optional_present(Rc::new(vec![])), |acc: _, edge: Rc<Edge>| match acc.clone() {
    std::option::Option::None => acc.clone(),
    Some(evidence_edges) => if is_metadata(edge.clone()) {
        crate::std_optional::optional_present(crate::std_algebra::list_snoc_item(evidence_edges.clone(), edge.clone()))
    } else {
        match lookup_inferred_facts_in_entries(entries.clone(), edge.target.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(child_facts) => match (*inferred_facts_resolved_type(child_facts.clone())).clone() {
    Witness::Violates { diagnostic: _, .. } => crate::std_optional::optional_absent(),
    Witness::Holds { value: child_evidence, .. } => crate::std_optional::optional_present(crate::std_algebra::list_snoc_item(evidence_edges.clone(), Rc::new(Edge {
    label: edge.label.clone(),
    target: child_evidence.clone(),
    declaration: edge.declaration.clone(),
}))),
},
}
    },
})
}

pub fn infer_formation_facts_from_entries(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, partials: Rc<Vec<Rc<Node>>>, resolved: Rc<ResolvedTree>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match crate::v2_std_node_query::binder_node_parts(node.clone()) {
    Some(parts) => infer_binder_node_facts_from_entries(node.clone(), parts.clone(), entries.clone()),
    std::option::Option::None => infer_type_decl_formation_facts_from_entries(node.clone(), entries.clone(), partials, resolved),
}
}

pub fn infer_type_decl_formation_facts_from_entries(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, partials: Rc<Vec<Rc<Node>>>, resolved: Rc<ResolvedTree>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*crate::v2_std_type_binder::type_decl_view(node.clone())).clone() {
    TypeDeclView::TypeAlias { .. } => infer_declaration_wrapper_facts_from_entries(node.clone(), entries.clone(), partials.clone()),
    TypeDeclView::GenericTypeDecl { .. } => infer_declaration_wrapper_facts_from_entries(node.clone(), entries.clone(), partials.clone()),
    TypeDeclView::OpaqueTypeDecl { binders: _, .. } => infer_opaque_declaration_facts(node.clone(), partials.clone()),
    TypeDeclView::NotATypeDecl => infer_declaration_wrapper_facts_from_entries(node.clone(), entries.clone(), partials.clone()),
    TypeDeclView::PlainTypeDecl { member: _, .. } => infer_product_facts_from_entries(node.clone(), entries.clone(), partials.clone(), resolved),
}
}

pub fn infer_binder_node_facts_from_entries(node: Rc<Node>, parts: Rc<BinderParts>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => match lookup_inferred_facts_in_entries(entries, parts.type_node.clone()) {
    std::option::Option::None => inferred_facts_not_derived(node.clone(), NotDerivedSite::BinderTypeNodeUnfacted, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    Some(type_facts) => match (*inferred_facts_resolved_type(type_facts.clone())).clone() {
    Witness::Violates { diagnostic: _, .. } => inferred_facts_not_derived(node.clone(), NotDerivedSite::BinderTypeUnjudged, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    Witness::Holds { value: type_evidence, .. } => inferred_facts_from_derived_type(node.clone(), crate::v2_std_node_query::binder_node(type_evidence.clone(), std::option::Option::None), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
},
},
}
}

pub fn infer_declaration_wrapper_facts_from_entries(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, partials: Rc<Vec<Rc<Node>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => match infer_formation_child_evidence_edges(node.children.clone(), entries, |edge| crate::v2_std_type_binder::edge_is_type_params(edge)) {
    std::option::Option::None => crate::v2_std_diagnostic::bind_outcome_accepted(cd.clone(), inferred_facts_not_derived(node.clone(), NotDerivedSite::DeclarationWrapperEvidenceEdgesAbsent, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
    Some(evidence_edges) => crate::v2_std_diagnostic::bind_outcome_accepted(cd.clone(), inferred_facts_from_derived_type(node.clone(), Rc::new(Node {
    kind: node.kind.clone(),
    children: evidence_edges.clone(),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
}), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
},
} },
}
}

pub fn infer_opaque_declaration_facts(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome_accepted(cd.clone(), inferred_facts_from_derived_type(node.clone(), crate::v2_std_kind::kind_node(Kind::TypeDenotationKind), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
} },
}
}

pub fn infer_product_facts_from_entries(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, partials: Rc<Vec<Rc<Node>>>, resolved: Rc<ResolvedTree>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match crate::v2_std_node_query::field_projection_optional(node.clone()) {
    Some(projection) => infer_field_projection_facts(node.clone(), projection.clone(), entries.clone(), partials.clone(), resolved),
    std::option::Option::None => match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => match infer_product_child_evidence_edges(node.clone(), entries.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::bind_outcome_accepted(cd.clone(), inferred_facts_not_derived(node.clone(), NotDerivedSite::ProductEvidenceEdgesAbsent, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
    Some(evidence_edges) => crate::v2_std_diagnostic::bind_outcome_accepted(cd.clone(), inferred_facts_from_derived_type(node.clone(), Rc::new(Node {
    kind: node.kind.clone(),
    children: evidence_edges.clone(),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
}), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
},
} },
},
}
}

pub fn infer_node_facts(n: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, kinds: Rc<Vec<Rc<RosterKindIndex>>>, resolved: Rc<ResolvedTree>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, binder_types: Rc<Vec<Rc<InferBinderType>>>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match crate::v2_std_qualified_name::parameter_reference_path_optional(n.clone()) {
    Some(path) => infer_parameter_reference_facts(n.clone(), path.clone(), resolved.resolved_declarations.clone()),
    std::option::Option::None => match crate::v2_std_qualified_name::lexical_reference_label_optional(n.clone()) {
    Some(_) => infer_lexical_reference_facts(n.clone(), resolved.clone(), instances, binder_types),
    std::option::Option::None => infer_term_node_facts(n.clone(), partials, kinds, resolved.clone(), rigid_binders),
},
}
}

pub fn infer_lexical_reference_facts(n: Rc<Node>, resolved: Rc<ResolvedTree>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, binder_types: Rc<Vec<Rc<InferBinderType>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*infer_descent_witness_for_node(n.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => match crate::v2_compiler_resolve::resolved_tree_lexical_binding(resolved, n.clone()) {
    Some(binding) => match infer_payload_binder_derived_type(binder_types, binding.clone()) {
    Some(derived) => inferred_facts_from_derived_type(n.clone(), derived.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    std::option::Option::None => match (*binding.standing.clone()).clone() {
    LexicalBinderStanding::LexicalOwedFormal { field_type: _, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(Rc::new(Diagnostic {
    reason: "infer_reason_pattern_payload_formal_uninstantiated".to_string(),
    at: crate::v2_std_diagnostic::node_locus(n.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
})),
}),
    LexicalBinderStanding::LexicalDeclared { node: declared, .. } => inferred_facts_from_derived_type(n.clone(), infer_frame_instantiated(declared.clone(), instances), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    LexicalBinderStanding::LexicalValued { node: _, .. } => inferred_facts_not_derived(n.clone(), NotDerivedSite::LexicalReferenceValued, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    LexicalBinderStanding::LexicalUntyped => inferred_facts_not_derived(n.clone(), NotDerivedSite::LexicalReferenceUntyped, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
},
},
    std::option::Option::None => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(Rc::new(Diagnostic {
    reason: "infer_reason_lexical_reference_unrecorded".to_string(),
    at: crate::v2_std_diagnostic::node_locus(n.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::UserInputBoundary),
}),
})),
}),
},
}
}

pub fn infer_payload_binder_derived_type(binder_types: Rc<Vec<Rc<InferBinderType>>>, binding: Rc<LexicalBinding>) -> Option<Rc<Node>> {
    binder_types.iter().cloned().fold(crate::std_optional::optional_absent(), |acc: Option<_>, row: Rc<InferBinderType>| match acc.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => if (row.site.clone() == binding.binder_site.clone()) {
        crate::std_optional::optional_present(row.derived.clone())
    } else {
        acc.clone()
    },
})
}

pub fn infer_parameter_reference_facts(n: Rc<Node>, path: QualifiedName, index: Rc<SymbolIndex>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*infer_descent_witness_for_node(n.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => match crate::v2_std_symbol_index::symbol_index_lookup(index, path) {
    Some(declared) => inferred_facts_from_derived_type(n.clone(), declared.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    std::option::Option::None => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(Rc::new(Diagnostic {
    reason: "infer_reason_parameter_reference_not_indexed".to_string(),
    at: crate::v2_std_diagnostic::node_locus(n.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::UserInputBoundary),
}),
})),
}),
},
}
}

pub fn infer_term_node_facts(n: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, kinds: Rc<Vec<Rc<RosterKindIndex>>>, resolved: Rc<ResolvedTree>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(n.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_descent_witness_for_node(n.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => match (*crate::v2_extdeps_languages_dag::dag_canonical_literal_from_node(n.clone())).clone() {
    Outcome::Accepted { value: ref __rc_value, .. } if matches!(__rc_value.as_ref(), DagCanonicalLiteral::DagCanonicalFloatLiteral { lexeme: _, .. }) => { let DagCanonicalLiteral::DagCanonicalFloatLiteral { lexeme: _, .. } = __rc_value.as_ref() else { unreachable!() }; Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(infer_float_literal_home_unruled_diagnostic(n.clone())),
}) },
    Outcome::Accepted { value: literal, .. } => match infer_literal_value_type(literal.clone()) {
    Some(literal_type) => inferred_facts_from_derived_type(n.clone(), literal_type.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    std::option::Option::None => inferred_facts_not_derived(n.clone(), NotDerivedSite::LiteralTypeUnknown, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
},
    Outcome::Rejected { diagnostics: _, .. } => match infer_node_declared_in_language_inhabitants(kinds, n.clone()) {
    Some(member_kind) => inferred_facts_from_derived_type(n.clone(), crate::v2_std_kind::kind_node(member_kind.clone()), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    std::option::Option::None => match infer_atom_binding_sym(n.clone()) {
    Some(binding) => match crate::v2_extdeps_languages_dag::dag_binding_denotation(binding.clone()) {
    Some(_) => inferred_facts_from_derived_type(n.clone(), crate::v2_std_kind::kind_node(Kind::TypeDenotationKind), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    std::option::Option::None => match infer_established_value_type_optional(n.clone()) {
    Some(_) => inferred_facts_from_derived_type(n.clone(), crate::v2_std_kind::kind_node(Kind::TypeDenotationKind), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    std::option::Option::None => match infer_roster_member_declared_type(n.clone()) {
    Some(member_type) => inferred_facts_from_derived_type(n.clone(), member_type.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    std::option::Option::None => if infer_atom_is_rigid_binder_in_scope(binding.clone(), rigid_binders) {
        inferred_facts_from_derived_type(n.clone(), infer_open_type_param_atom(binding.clone()), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))
    } else {
        inferred_facts_not_derived(n.clone(), NotDerivedSite::RosterMemberTypeAbsent, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))
    },
},
},
},
    std::option::Option::None => infer_declaration_reference_facts(n.clone(), resolved, descent_proof.clone()),
},
},
},
} },
}
}

pub fn infer_field_projection_facts(node: Rc<Node>, projection: Rc<FieldProjection>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, partials: Rc<Vec<Rc<Node>>>, resolved: Rc<ResolvedTree>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => match (*infer_projection_receiver(projection.base.clone(), entries, resolved.clone())).clone() {
    ProjectionReceiver::ReceiverTypeUnderived => crate::v2_std_diagnostic::bind_outcome_accepted(cd.clone(), inferred_facts_not_derived(node.clone(), NotDerivedSite::ProjectionReceiverUnderived, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
    ProjectionReceiver::ReceiverTypeNotADeclaration => crate::v2_std_diagnostic::outcome_rejected(infer_receiver_declares_no_fields_diagnostic(node.clone())),
    ProjectionReceiver::ReceiverDeclarationUnavailable { path: path, .. } => Rc::new(Outcome::Rejected {
    diagnostics: infer_closure_miss_refusal(resolved.clone(), path.clone(), infer_receiver_declaration_unavailable_diagnostic(node.clone())),
}),
    ProjectionReceiver::ReceiverArityMismatch => crate::v2_std_diagnostic::outcome_rejected(infer_receiver_arity_mismatch_diagnostic(node.clone())),
    ProjectionReceiver::ReceiverPayload { payload, instances, .. } => match crate::v2_std_node_query::declared_field_named(payload.clone(), projection.field.clone()) {
    Some(declared) => crate::v2_std_diagnostic::bind_outcome_accepted(cd.clone(), inferred_facts_from_derived_type(node.clone(), infer_projected_field_type(declared.type_node.clone(), instances.clone()), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_field_not_declared_diagnostic(node.clone())),
},
},
} },
}
}

pub fn infer_projected_field_type(field_type: Rc<Node>, instances: Rc<Vec<Rc<TypeVariableInstance>>>) -> Rc<Node> {
    if (crate::std_algebra::length(instances.clone()) == 0) {
        field_type.clone()
    } else {
        infer_type_instantiated(field_type.clone(), instances.clone())
    }
}

