pub fn infer_declaration_callable_evidence(declared: Rc<Node>) -> Option<Rc<Node>> {
    match infer_operator_arrow(declared) {
    std::option::Option::None => std::option::Option::None,
    Some(arrow) => match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(arrow.clone()), 0) {
    std::option::Option::None => std::option::Option::None,
    Some(domain) => match infer_formals_from_domain(domain.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(_formals) => match (*crate::v2_std_arrow_signature::arrow_declared_parameter_order(arrow.clone())).clone() {
    ArrowParameterOrder::ArrowParameterOrderAbsent => std::option::Option::None,
    ArrowParameterOrder::ArrowParameterOrderMalformed => std::option::Option::None,
    ArrowParameterOrder::ArrowParameterOrderDeclared { labels: _, .. } => Some(arrow.clone()),
},
},
},
}
}

pub fn infer_reference_facts_or_frontier(o: Rc<Outcome<Rc<InferredFacts>>>, n: Rc<Node>, descent_proof: Rc<TerminationProof>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*o.clone()).clone() {
    Outcome::Accepted { value: facts, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(d.clone()),
}) },
    Outcome::Rejected { diagnostics: _, .. } => inferred_facts_not_derived(n, NotDerivedSite::ReferenceRejectedGrounding, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
}
}

pub fn infer_declaration_reference_facts(n: Rc<Node>, resolved: Rc<ResolvedTree>, descent_proof: Rc<TerminationProof>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match crate::v2_std_qualified_name::declaration_reference_path_optional(n.clone()) {
    std::option::Option::None => inferred_facts_not_derived(n.clone(), NotDerivedSite::DeclarationReferenceWithoutPath, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    Some(path) => match (*crate::v2_compiler_fold_lowering::collection_roster_primitive_call_signature_at(crate::v2_std_qualified_name::qualified_name_to_dotted_string(path.clone()))).clone() {
    RosterSignatureLookup::NotARosterPrimitiveCallRow => infer_declaration_reference_facts_indexed(n.clone(), resolved, path.clone(), descent_proof.clone()),
    RosterSignatureLookup::RosterPrimitiveCallSignature { arrow: callable, .. } => infer_roster_reference_facts(Rc::new(RosterSignatureLookup::RosterPrimitiveCallSignature {
    arrow: callable.clone(),
}), n.clone(), descent_proof.clone()),
    RosterSignatureLookup::RosterPrimitiveCallSignatureUnreadable => infer_roster_reference_facts(Rc::new(RosterSignatureLookup::RosterPrimitiveCallSignatureUnreadable), n.clone(), descent_proof.clone()),
},
}
}

pub fn infer_roster_reference_facts(lookup: Rc<RosterSignatureLookup>, n: Rc<Node>, descent_proof: Rc<TerminationProof>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*lookup.clone()).clone() {
    RosterSignatureLookup::RosterPrimitiveCallSignature { arrow: callable, .. } => infer_reference_facts_or_frontier(inferred_facts_from_derived_type(n.clone(), callable.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), n.clone(), descent_proof.clone()),
    RosterSignatureLookup::RosterPrimitiveCallSignatureUnreadable => crate::v2_std_diagnostic::outcome_rejected(Rc::new(Diagnostic {
    reason: "infer_reason_roster_row_signature_unreadable".to_string(),
    at: crate::v2_std_diagnostic::node_locus(n.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})),
    RosterSignatureLookup::NotARosterPrimitiveCallRow => crate::v2_std_diagnostic::outcome_rejected(Rc::new(Diagnostic {
    reason: "infer_reason_roster_reference_without_a_row".to_string(),
    at: crate::v2_std_diagnostic::node_locus(n.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})),
}
}

pub fn infer_declaration_reference_facts_indexed(n: Rc<Node>, resolved: Rc<ResolvedTree>, path: QualifiedName, descent_proof: Rc<TerminationProof>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match infer_resolved_lookup(resolved.clone(), path.clone()) {
    std::option::Option::None => match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(resolved.symbol_index.clone(), path.clone())).clone() {
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: claimants, .. } => infer_declaration_identity_contested_rejected(n.clone(), claimants.clone()),
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_declaration_body_unavailable_diagnostic(n.clone())),
    MentionDeclaringIdentity::MentionDeclaringUnavailable => crate::v2_std_diagnostic::bind_outcome_accepted(infer_closure_miss_cause(resolved.clone(), path.clone()), inferred_facts_not_derived(n.clone(), NotDerivedSite::ReferenceLookupMiss, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
},
    Some(declared) => match infer_resolved_payload(resolved.clone(), path.clone()) {
    Some(DeclaredPayloadKind::VariantArmPayload) => infer_variant_arm_value_reference_facts(n.clone(), resolved.clone(), path.clone(), declared.clone(), descent_proof.clone()),
    Some(DeclaredPayloadKind::RecordTypePayload) => infer_declaration_callable_reference_facts(n.clone(), declared.clone(), descent_proof.clone()),
    std::option::Option::None => infer_declaration_callable_reference_facts(n.clone(), declared.clone(), descent_proof.clone()),
},
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum InferVariantArmReferenceValue {
    VariantArmReferenceValueCoproduct {
        coproduct: QualifiedName,
    },
    VariantArmReferenceValueNotDerived,
    VariantArmReferenceValueIdentityUnavailable,
    VariantArmReferenceValueIdentityContested {
        claimants: Rc<Vec<QualifiedName>>,
    },
    VariantArmReferenceValueBodyUnavailable,
}

pub fn infer_open_type_param_atom(name: std::string::String) -> Rc<Node> {
    Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Atom {
    identity: name.clone(),
}),
}),
    children: Rc::new(vec![]),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
})
}

pub fn infer_coproduct_type_applied_open(bindings: Rc<SymbolIndex>, coproduct: QualifiedName, use_id: OccurrenceId) -> Rc<Node> {
    {
        let head = crate::v2_std_qualified_name::declaration_reference_node(coproduct.clone(), Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic));
let params = crate::v2_std_symbol_index::symbol_index_declared_type_params_at(bindings, coproduct.clone());
{ let __fm = params.clone(); if __fm.is_empty() { head.clone() } else { Rc::new(Node {
    kind: Rc::new(NodeKind::TypeNode {
    connective: Rc::new(Connective::Instantiation),
}),
    children: Rc::new({ let mut __cons_v = (*crate::std_algebra::list_map(params.clone(), |p| Rc::new(Edge {
    label: Rc::new(EdgeLabel::Positional),
    target: infer_open_type_param_atom(crate::v2_std_anonymous_binder::fresh_constructor_use_variable(use_id.value.clone(), p)),
    declaration: Rc::new(EdgeDeclaration::NotADeclaration),
}))).clone(); __cons_v.insert(0, Rc::new(Edge {
    label: Rc::new(EdgeLabel::Positional),
    target: head.clone(),
    declaration: Rc::new(EdgeDeclaration::NotADeclaration),
})); __cons_v }),
    occurrence_id: Rc::new(NodeOccurrenceIdentity::OccurrenceSynthetic),
}) } }
}
}

pub fn infer_variant_arm_reference_value_joined(bindings: Rc<SymbolIndex>, arm_path: QualifiedName, declared: Rc<Node>) -> Rc<InferVariantArmReferenceValue> {
    match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(bindings.clone(), arm_path.clone())).clone() {
    MentionDeclaringIdentity::MentionDeclaringUnavailable => Rc::new(InferVariantArmReferenceValue::VariantArmReferenceValueIdentityUnavailable),
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: claimants, .. } => Rc::new(InferVariantArmReferenceValue::VariantArmReferenceValueIdentityContested {
    claimants: claimants.clone(),
}),
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: _, .. } => match infer_coproduct_path_of_variant_arm_joined(bindings.clone(), arm_path.clone()) {
    std::option::Option::None => Rc::new(InferVariantArmReferenceValue::VariantArmReferenceValueIdentityUnavailable),
    Some(coproduct) => if infer_empty_product_shape(declared) {
        Rc::new(InferVariantArmReferenceValue::VariantArmReferenceValueCoproduct {
    coproduct: coproduct.clone(),
})
    } else {
        Rc::new(InferVariantArmReferenceValue::VariantArmReferenceValueNotDerived)
    },
},
}
}

pub fn infer_variant_arm_reference_value_optional(node: Rc<Node>, resolved: Rc<ResolvedTree>) -> Option<Rc<InferVariantArmReferenceValue>> {
    match crate::v2_std_qualified_name::declaration_reference_path_optional(node) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(path) => match infer_resolved_lookup(resolved.clone(), path.clone()) {
    std::option::Option::None => match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(resolved.symbol_index.clone(), path.clone())).clone() {
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: claimants, .. } => crate::std_optional::optional_present(Rc::new(InferVariantArmReferenceValue::VariantArmReferenceValueIdentityContested {
    claimants: claimants.clone(),
})),
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: _, .. } => crate::std_optional::optional_present(Rc::new(InferVariantArmReferenceValue::VariantArmReferenceValueBodyUnavailable)),
    MentionDeclaringIdentity::MentionDeclaringUnavailable => crate::std_optional::optional_absent(),
},
    Some(declared) => match infer_resolved_payload(resolved.clone(), path.clone()) {
    Some(DeclaredPayloadKind::VariantArmPayload) => crate::std_optional::optional_present(infer_variant_arm_reference_value_joined(resolved.symbol_index.clone(), path.clone(), declared.clone())),
    Some(DeclaredPayloadKind::RecordTypePayload) => crate::std_optional::optional_absent(),
    std::option::Option::None => crate::std_optional::optional_absent(),
},
},
}
}

pub fn infer_nullary_zero_param_coproduct_arm_use(node: Rc<Node>, index: Rc<SymbolIndex>, facts: Rc<InferredFacts>) -> bool {
    match facts.denotation.clone() {
    std::option::Option::None => false,
    Some(_) => infer_nullary_zero_param_coproduct_arm_declared(node, index),
}
}

pub fn infer_nullary_zero_param_coproduct_arm_declared(node: Rc<Node>, index: Rc<SymbolIndex>) -> bool {
    match crate::v2_std_qualified_name::declaration_reference_path_optional(node) {
    std::option::Option::None => false,
    Some(path) => match crate::v2_std_symbol_index::symbol_index_lookup(index.clone(), path.clone()) {
    std::option::Option::None => false,
    Some(declared) => if !infer_empty_product_shape(declared.clone()) {
        false
    } else {
        match (*infer_variant_arm_reference_value_joined(index.clone(), path.clone(), declared.clone())).clone() {
    InferVariantArmReferenceValue::VariantArmReferenceValueIdentityUnavailable => false,
    InferVariantArmReferenceValue::VariantArmReferenceValueIdentityContested { claimants: _, .. } => false,
    InferVariantArmReferenceValue::VariantArmReferenceValueBodyUnavailable => false,
    InferVariantArmReferenceValue::VariantArmReferenceValueNotDerived => false,
    InferVariantArmReferenceValue::VariantArmReferenceValueCoproduct { coproduct: coproduct, .. } => { let __fm = crate::v2_std_symbol_index::symbol_index_declared_type_params_at(index.clone(), coproduct.clone()); if __fm.is_empty() { true } else { false } },
}
    },
},
}
}

pub fn infer_variant_arm_value_reference_facts(n: Rc<Node>, resolved: Rc<ResolvedTree>, path: QualifiedName, declared: Rc<Node>, descent_proof: Rc<TerminationProof>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*infer_variant_arm_reference_value_joined(resolved.symbol_index.clone(), path, declared.clone())).clone() {
    InferVariantArmReferenceValue::VariantArmReferenceValueIdentityUnavailable => crate::v2_std_diagnostic::outcome_rejected(infer_declaration_identity_unavailable_diagnostic(n.clone())),
    InferVariantArmReferenceValue::VariantArmReferenceValueIdentityContested { claimants: claimants, .. } => infer_declaration_identity_contested_rejected(n.clone(), claimants.clone()),
    InferVariantArmReferenceValue::VariantArmReferenceValueBodyUnavailable => crate::v2_std_diagnostic::outcome_rejected(infer_declaration_body_unavailable_diagnostic(n.clone())),
    InferVariantArmReferenceValue::VariantArmReferenceValueNotDerived => inferred_facts_not_derived(n.clone(), NotDerivedSite::VariantArmValueNotDerived, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    InferVariantArmReferenceValue::VariantArmReferenceValueCoproduct { coproduct: coproduct, .. } => match crate::v2_std_provenance::node_occurrence_id_optional(n.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_declaration_identity_unavailable_diagnostic(n.clone())),
    Some(use_id) => infer_reference_facts_or_frontier(infer_facts_denoting(inferred_facts_from_derived_type(n.clone(), infer_coproduct_type_applied_open(resolved.symbol_index.clone(), coproduct.clone(), use_id.clone()), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), declared.clone()), n.clone(), descent_proof.clone()),
},
}
}

pub fn infer_declaration_callable_reference_facts(n: Rc<Node>, declared: Rc<Node>, descent_proof: Rc<TerminationProof>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match infer_declaration_callable_evidence(declared.clone()) {
    std::option::Option::None => inferred_facts_not_derived(n.clone(), NotDerivedSite::CallableEvidenceAbsent, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})),
    Some(callable) => infer_reference_facts_or_frontier(infer_facts_denoting(inferred_facts_from_derived_type(n.clone(), infer_reference_value_type(callable.clone()), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), declared.clone()), n.clone(), descent_proof.clone()),
}
}

