pub fn inferred_facts_index_enter(index: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, entry: Rc<InferredFactsEntry>) -> Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>> {
    match v1_rt::lookup(&index, entry.node.clone()) {
    Some(xs) => v1_rt::rc_map_insert(index.clone(), entry.node.clone(), crate::std_algebra::list_snoc_item(xs.clone(), entry.facts.clone())),
    std::option::Option::None => v1_rt::rc_map_insert(index.clone(), entry.node.clone(), Rc::new(vec![entry.facts.clone()])),
}
}

pub fn inferred_facts_index_enter_first(index: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, entry: Rc<InferredFactsEntry>) -> Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>> {
    match v1_rt::lookup(&index, entry.node.clone()) {
    Some(xs) => v1_rt::rc_map_insert(index.clone(), entry.node.clone(), Rc::new({ let mut __cons_v = (*xs.clone()).clone(); __cons_v.insert(0, entry.facts.clone()); __cons_v })),
    std::option::Option::None => v1_rt::rc_map_insert(index.clone(), entry.node.clone(), Rc::new(vec![entry.facts.clone()])),
}
}

pub fn lookup_inferred_facts_in_entries(entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, key: Rc<Node>) -> Option<Rc<InferredFacts>> {
    match v1_rt::lookup(&entries, key) {
    Some(xs) => { let __fm = xs.clone(); if __fm.len() >= 1 { let first = (*__fm)[0].clone(); crate::std_optional::optional_present(first.clone()) } else { crate::std_optional::optional_absent() } },
    std::option::Option::None => crate::std_optional::optional_absent(),
}
}

