pub fn infer_conj_named_type_for_binding(domain: Rc<Node>, binding: std::string::String) -> Option<Rc<Node>> {
    match (*domain.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => domain.children.clone().iter().cloned().fold(std::option::Option::None, |acc: Option<Rc<Node>>, e: Rc<Edge>| match acc.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => infer_conj_edge_named_type_for_binding(e.clone(), binding.clone()),
}),
    _ => std::option::Option::None,
} },
    NodeKind::ComputationNode { behavior: _, .. } => std::option::Option::None,
}
}

