pub fn infer_branch_bool_if_else_admitted(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match crate::v2_std_node::branch_slot_target(node.clone(), BranchSlot::BranchConditionSlot) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_branch_shape_invalid_diagnostic(node.clone())),
    Some(cond_target) => match crate::v2_std_node::branch_slot_target(node.clone(), BranchSlot::BranchThenSlot) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_branch_shape_invalid_diagnostic(node.clone())),
    Some(then_target) => match crate::v2_std_node::branch_slot_target(node.clone(), BranchSlot::BranchElseSlot) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_branch_else_less_as_value_diagnostic(node.clone())),
    Some(else_target) => match lookup_inferred_facts_in_entries(entries.clone(), cond_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(cond_target.clone())),
    Some(_) => match lookup_inferred_facts_in_entries(entries.clone(), then_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(then_target.clone())),
    Some(then_facts) => match lookup_inferred_facts_in_entries(entries.clone(), else_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(else_target.clone())),
    Some(else_facts) => match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_unify_branch_arm_types(then_target.clone(), then_facts.clone(), else_target.clone(), else_facts.clone(), resolved)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: unified_type, diagnostics: ref __rc_diagnostics, .. } => { let ud = __rc_diagnostics.as_ref(); match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome(inferred_facts_from_derived_type(node.clone(), unified_type.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), |facts| Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(crate::v2_std_diagnostic::diagnostics_merge(cd.clone(), ud.clone())),
})),
} },
} },
},
},
},
},
},
},
}
}

