#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum InferBoolLiteralExhaustiveness {
    InferBoolLiteralExhaustive,
    InferBoolLiteralMissingTrue,
    InferBoolLiteralMissingFalse,
    InferBoolLiteralMissingBoth,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferMatchArmRow {
    pub coverage: InferBoolLiteralArmCoverage,
    pub body_type: Rc<Node>,
}

pub fn infer_bool_literal_pattern_classify(pattern: Rc<Node>) -> InferBoolLiteralPattern {
    match (*crate::v2_extdeps_languages_dag::dag_canonical_literal_from_node(pattern)).clone() {
    Outcome::Accepted { value: ref __rc_value, .. } => { match __rc_value.as_ref() {
    DagCanonicalLiteral::DagCanonicalBoolLiteral { value: true, .. } => InferBoolLiteralPattern::InferBoolLiteralPatternTrue,
    DagCanonicalLiteral::DagCanonicalBoolLiteral { value: false, .. } => InferBoolLiteralPattern::InferBoolLiteralPatternFalse,
    DagCanonicalLiteral::DagCanonicalIntLiteral { magnitude: _, .. } => InferBoolLiteralPattern::InferBoolLiteralPatternOther,
    DagCanonicalLiteral::DagCanonicalSymbolLiteral { symbol: _, .. } => InferBoolLiteralPattern::InferBoolLiteralPatternOther,
    DagCanonicalLiteral::DagCanonicalStringLiteral { value: _, .. } => InferBoolLiteralPattern::InferBoolLiteralPatternOther,
    DagCanonicalLiteral::DagCanonicalFloatLiteral { lexeme: _, .. } => InferBoolLiteralPattern::InferBoolLiteralPatternOther,
} },
    Outcome::Rejected { diagnostics: _, .. } => InferBoolLiteralPattern::InferBoolLiteralPatternOther,
}
}

pub fn infer_bool_literal_arm_coverage_from_pattern(pattern: Rc<Node>) -> InferBoolLiteralArmCoverage {
    match infer_bool_literal_pattern_classify(pattern) {
    InferBoolLiteralPattern::InferBoolLiteralPatternTrue => InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversTrue,
    InferBoolLiteralPattern::InferBoolLiteralPatternFalse => InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversFalse,
    InferBoolLiteralPattern::InferBoolLiteralPatternOther => InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversNeither,
}
}

pub fn infer_bool_literal_exhaustiveness_merge(left: InferBoolLiteralArmCoverage, right: InferBoolLiteralArmCoverage) -> InferBoolLiteralExhaustiveness {
    match left.clone() {
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversTrue => match right.clone() {
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversTrue => InferBoolLiteralExhaustiveness::InferBoolLiteralMissingFalse,
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversFalse => InferBoolLiteralExhaustiveness::InferBoolLiteralExhaustive,
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversNeither => InferBoolLiteralExhaustiveness::InferBoolLiteralMissingFalse,
},
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversFalse => match right.clone() {
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversTrue => InferBoolLiteralExhaustiveness::InferBoolLiteralExhaustive,
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversFalse => InferBoolLiteralExhaustiveness::InferBoolLiteralMissingTrue,
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversNeither => InferBoolLiteralExhaustiveness::InferBoolLiteralMissingTrue,
},
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversNeither => match right.clone() {
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversTrue => InferBoolLiteralExhaustiveness::InferBoolLiteralMissingFalse,
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversFalse => InferBoolLiteralExhaustiveness::InferBoolLiteralMissingTrue,
    InferBoolLiteralArmCoverage::InferBoolLiteralArmCoversNeither => InferBoolLiteralExhaustiveness::InferBoolLiteralMissingBoth,
},
}
}

pub fn infer_match_bool_literal_arm_row(pat: Rc<Node>, pd: Option<Rc<NonEmptyDiagnostics>>, body_target: Rc<Node>, bd: Option<Rc<NonEmptyDiagnostics>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, scrutinee_type: Rc<Node>) -> Rc<Outcome<Rc<InferMatchArmRow>>> {
    {
        let coverage = infer_bool_literal_arm_coverage_from_pattern(pat);
match lookup_inferred_facts_in_entries(entries, body_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(body_target.clone())),
    Some(body_facts) => match (*infer_match_bool_arm_body_type(body_target.clone(), body_facts.clone(), scrutinee_type)).clone() {
    Witness::Violates { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    Witness::Holds { value: body_type, .. } => Rc::new(Outcome::Accepted {
    value: Rc::new(InferMatchArmRow {
    coverage: coverage.clone(),
    body_type: body_type.clone(),
}),
    diagnostics: Box::new(crate::v2_std_diagnostic::diagnostics_merge(pd, bd)),
}),
},
}
}
}

pub fn infer_match_bool_arm_row(arm: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, scrutinee_type: Rc<Node>) -> Rc<Outcome<Rc<InferMatchArmRow>>> {
    match (*arm.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => match (*crate::v2_std_node_query::find_core_child(arm.clone(), Rc::new(CoreEdgeLabel::MatchArmPatternEdge))).clone() {
    Outcome::Rejected { diagnostics: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
    Outcome::Accepted { value: pat, diagnostics: ref __rc_diagnostics, .. } => { let pd = __rc_diagnostics.as_ref(); match (*crate::v2_std_node_query::find_core_child(arm.clone(), Rc::new(CoreEdgeLabel::MatchArmBodyEdge))).clone() {
    Outcome::Rejected { diagnostics: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
    Outcome::Accepted { value: body_target, diagnostics: ref __rc_diagnostics, .. } => { let bd = __rc_diagnostics.as_ref(); match infer_bool_literal_pattern_classify(pat.clone()) {
    InferBoolLiteralPattern::InferBoolLiteralPatternOther => crate::v2_std_diagnostic::outcome_rejected(infer_match_pattern_not_bool_literal_diagnostic(arm.clone())),
    InferBoolLiteralPattern::InferBoolLiteralPatternTrue => infer_match_bool_literal_arm_row(pat.clone(), pd.clone(), body_target.clone(), bd.clone(), entries.clone(), scrutinee_type.clone()),
    InferBoolLiteralPattern::InferBoolLiteralPatternFalse => infer_match_bool_literal_arm_row(pat.clone(), pd.clone(), body_target.clone(), bd.clone(), entries.clone(), scrutinee_type.clone()),
} },
} },
},
    Connective::Atom { identity: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
    Connective::Disj => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
    Connective::Arrow => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
    Connective::Instantiation => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
} },
    NodeKind::ComputationNode { behavior: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
}
}

pub fn infer_match_bool(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>, expected: Option<Rc<Node>>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    {
        let arm_targets = crate::std_algebra::list_map(crate::v2_std_node::match_role_slots(node.clone(), MatchSlot::MatchArmSlot), |a| crate::v2_std_node::child_slot_target(a));
if (!crate::v2_std_node::all_edges_positional(node.children.clone()) || (crate::std_algebra::length(arm_targets.clone()) != 2)) {
            crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(node.clone()))
        } else {
            match crate::v2_std_node::match_slot_target(node.clone(), MatchSlot::MatchScrutineeSlot) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(node.clone())),
    Some(scrutinee_target) => { let __fm = arm_targets.clone(); if __fm.len() == 2 { let first_arm_target = (*__fm)[0].clone(); let second_arm_target = (*__fm)[1].clone(); match lookup_inferred_facts_in_entries(entries.clone(), scrutinee_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(scrutinee_target.clone())),
    Some(scrutinee_facts) => match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_branch_operand_resolved_type_with_entries(scrutinee_target.clone(), scrutinee_facts.clone(), entries.clone(), infer_no_type_variable_instances(), resolved.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    Witness::Holds { value: scrutinee_type, .. } => if (infer_branch_type_is_bool(scrutinee_type.clone()) || infer_branch_type_is_int(scrutinee_type.clone())) {
                infer_match_bool_arm_rows_accept(node.clone(), partials.clone(), entries.clone(), first_arm_target.clone(), second_arm_target.clone(), infer_match_bool_consumer_diagnostics_with_int_scrutinee_scaffold(node.clone(), cd.clone(), scrutinee_type.clone()), scrutinee_type.clone(), expected, resolved.clone(), rigid_binders)
            } else {
                crate::v2_std_diagnostic::outcome_rejected(infer_match_scrutinee_not_bool_diagnostic(node.clone()))
            },
} },
},
} } else { crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(node.clone())) } },
}
        }
}
}

pub fn infer_match_arm_pattern_is_literal(arm: Rc<Node>) -> bool {
    match (*crate::v2_std_node_query::find_core_child(arm, Rc::new(CoreEdgeLabel::MatchArmPatternEdge))).clone() {
    Outcome::Rejected { diagnostics: _, .. } => false,
    Outcome::Accepted { value: pat, .. } => match (*crate::v2_extdeps_languages_dag::dag_canonical_literal_from_node(pat.clone())).clone() {
    Outcome::Accepted { .. } => true,
    Outcome::Rejected { diagnostics: _, .. } => false,
},
}
}

pub fn infer_match_arm_pattern_is_constructor(arm: Rc<Node>) -> bool {
    match (*crate::v2_std_node_query::find_core_child(arm, Rc::new(CoreEdgeLabel::MatchArmPatternEdge))).clone() {
    Outcome::Rejected { diagnostics: _, .. } => false,
    Outcome::Accepted { value: pat, .. } => match (*infer_coproduct_arm_pattern(pat.clone())).clone() {
    InferCoproductArmPattern::ArmPatternVariant { .. } => true,
    InferCoproductArmPattern::ArmPatternWildcard => false,
    InferCoproductArmPattern::ArmPatternBinder { name: _, .. } => false,
    InferCoproductArmPattern::ArmPatternUnread => false,
},
}
}

pub fn infer_match(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>, expected: Option<Rc<Node>>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    {
        let arms = crate::std_algebra::list_map(crate::v2_std_node::match_role_slots(node.clone(), MatchSlot::MatchArmSlot), |a| crate::v2_std_node::child_slot_target(a));
if crate::std_algebra::is_empty(arms.clone()) {
            infer_match_coproduct(node.clone(), partials.clone(), entries.clone(), resolved.clone(), expected.clone(), rigid_binders.clone())
        } else {
            if { let mut __found = false; for arm in arms.iter().cloned() { if infer_match_arm_pattern_is_literal(arm.clone()) { __found = true; break; } } __found } {
                infer_match_bool(node.clone(), partials.clone(), entries.clone(), resolved.clone(), expected.clone(), rigid_binders.clone())
            } else {
                if { let mut __found = false; for arm in arms.iter().cloned() { if infer_match_arm_pattern_is_constructor(arm.clone()) { __found = true; break; } } __found } {
                    infer_match_coproduct(node.clone(), partials.clone(), entries.clone(), resolved.clone(), expected.clone(), rigid_binders.clone())
                } else {
                    infer_match_bool(node.clone(), partials.clone(), entries.clone(), resolved.clone(), expected.clone(), rigid_binders.clone())
                }
            }
        }
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferMatchCoproduct {
    pub path: QualifiedName,
    pub variants: Rc<Node>,
    pub instances: Rc<Vec<Rc<TypeVariableInstance>>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferMatchCoproductRead {
    CoproductRead {
        coproduct: Rc<InferMatchCoproduct>,
    },
    UninhabitedScrutinee,
    CoproductNotDeclared,
    CoproductArityMismatch,
}
impl InferMatchCoproductRead {
    pub fn coproduct(&self) -> Rc<InferMatchCoproduct> {
        match self {
            InferMatchCoproductRead::CoproductRead { coproduct: __val, .. } => __val.clone(),
            InferMatchCoproductRead::UninhabitedScrutinee => panic!("no coproduct on unit variant"),
            InferMatchCoproductRead::CoproductNotDeclared => panic!("no coproduct on unit variant"),
            InferMatchCoproductRead::CoproductArityMismatch => panic!("no coproduct on unit variant"),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferTypeHeadArgs {
    pub head: Rc<Node>,
    pub args: Rc<Vec<Rc<Node>>>,
}

pub fn infer_type_head_and_args(t: Rc<Node>) -> Rc<InferTypeHeadArgs> {
    match (*t.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Instantiation => {
        let targets = crate::v2_std_node::positional_child_target_nodes(t.clone());
match v1_rt::list_get_optional(&targets, 0) {
    std::option::Option::None => Rc::new(InferTypeHeadArgs {
    head: t.clone(),
    args: Rc::new(vec![]),
}),
    Some(head) => Rc::new(InferTypeHeadArgs {
    head: head.clone(),
    args: crate::std_algebra::skip(targets.clone(), 1),
}),
}
},
    _ => Rc::new(InferTypeHeadArgs {
    head: t.clone(),
    args: Rc::new(vec![]),
}),
} },
    NodeKind::ComputationNode { behavior: _, .. } => Rc::new(InferTypeHeadArgs {
    head: t.clone(),
    args: Rc::new(vec![]),
}),
}
}

pub fn infer_match_path_is_never_type(path: QualifiedName, constructing_module: Option<std::string::String>) -> bool {
    match crate::v2_std_qualified_name::qualified_name_last_segment(path.clone()) {
    std::option::Option::None => false,
    Some(last) => {
        let init = crate::v2_std_qualified_name::qualified_name_to_dotted_string(crate::v2_std_qualified_name::qualified_name_init(path.clone()));
let module_path = if (init.clone() != "".to_string()) {
            init.clone()
        } else {
            match constructing_module.clone() {
    std::option::Option::None => "".to_string(),
    Some(m) => v1_rt::symbol_lexeme(m.clone()),
}
        };
if (module_path.clone() == "".to_string()) {
            false
        } else {
            crate::std_decl_ref::declaration_ref_eq(crate::std_decl_ref::decl_ref(module_path.clone(), v1_rt::symbol_lexeme(last.clone())), never_type_declaration())
        }
},
}
}

pub fn infer_match_coproduct_of_type(scrutinee_type: Rc<Node>, resolved: Rc<ResolvedTree>) -> Rc<InferMatchCoproductRead> {
    match crate::v2_std_qualified_name::declaration_denotation_of_type(infer_type_alias_normalized_at(scrutinee_type, resolved.resolved_declarations.clone(), resolved.symbol_index.clone())) {
    std::option::Option::None => Rc::new(InferMatchCoproductRead::CoproductNotDeclared),
    Some(denotation) => match crate::v2_std_symbol_index::symbol_index_lookup(resolved.resolved_declarations.clone(), denotation.declaration.clone()) {
    std::option::Option::None => Rc::new(InferMatchCoproductRead::CoproductNotDeclared),
    Some(declared) => if infer_match_path_is_never_type(denotation.declaration.clone(), resolved.constructing_module.clone()) {
        Rc::new(InferMatchCoproductRead::UninhabitedScrutinee)
    } else {
        match (*declared.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Disj => if crate::std_algebra::is_empty(declared.children.clone()) {
            Rc::new(InferMatchCoproductRead::UninhabitedScrutinee)
        } else {
            {
                let params = crate::v2_std_symbol_index::symbol_index_declared_type_params_at(resolved.resolved_declarations.clone(), denotation.declaration.clone());
if (crate::std_algebra::length(params.clone()) != crate::std_algebra::length(denotation.type_arguments.clone())) {
                    Rc::new(InferMatchCoproductRead::CoproductArityMismatch)
                } else {
                    Rc::new(InferMatchCoproductRead::CoproductRead {
    coproduct: Rc::new(InferMatchCoproduct {
    path: denotation.declaration.clone(),
    variants: declared.clone(),
    instances: crate::std_algebra::zip_map(params.clone(), denotation.type_arguments.clone(), |p, arg| Rc::new(TypeVariableInstance {
    binder: p.clone(),
    instance: arg.clone(),
})),
}),
})
                }
}
        },
    _ => Rc::new(InferMatchCoproductRead::CoproductNotDeclared),
} },
    NodeKind::ComputationNode { behavior: _, .. } => Rc::new(InferMatchCoproductRead::CoproductNotDeclared),
}
    },
},
}
}

pub fn infer_match_field_type_instantiated(field_type: Rc<Node>, instances: Rc<Vec<Rc<TypeVariableInstance>>>) -> Option<Rc<Node>> {
    match (*field_type.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: id, .. } => if ((field_type.children.clone().len() as i64) == 0) {
        match crate::v2_std_inhabitance::type_variable_instance_lookup(instances.clone(), id.clone()) {
    Some(instance) => crate::std_optional::optional_present(instance.clone()),
    std::option::Option::None => crate::v2_extdeps_languages_dag::dag_binding_denotation(id.clone()),
}
    } else {
        crate::std_optional::optional_absent()
    },
    _ => if infer_declared_type_mentions_free_formal(field_type.clone(), instances.clone()) {
        crate::std_optional::optional_absent()
    } else {
        crate::std_optional::optional_present(infer_type_instantiated(field_type.clone(), instances.clone()))
    },
} },
    NodeKind::ComputationNode { behavior: _, .. } => std::option::Option::None,
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferCoproductArmPattern {
    ArmPatternVariant {
        tag: Symbol,
        fields: Rc<Vec<Rc<Edge>>>,
    },
    ArmPatternWildcard,
    ArmPatternBinder {
        name: Symbol,
    },
    ArmPatternUnread,
}

pub fn infer_coproduct_arm_pattern(pat: Rc<Node>) -> Rc<InferCoproductArmPattern> {
    match crate::v2_std_qualified_name::lexical_reference_label_optional(pat.clone()) {
    Some(name) => Rc::new(InferCoproductArmPattern::ArmPatternBinder {
    name: name.clone(),
}),
    std::option::Option::None => match (*pat.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: _, .. } => if crate::v2_std_node_query::is_wildcard_pattern(pat.clone()) {
        Rc::new(InferCoproductArmPattern::ArmPatternWildcard)
    } else {
        Rc::new(InferCoproductArmPattern::ArmPatternUnread)
    },
    _ => infer_coproduct_arm_pattern_constructed(pat.clone()),
} },
    NodeKind::ComputationNode { behavior: _, .. } => infer_coproduct_arm_pattern_constructed(pat.clone()),
},
}
}

pub fn infer_coproduct_arm_pattern_constructed(pat: Rc<Node>) -> Rc<InferCoproductArmPattern> {
    match crate::v2_std_qualified_name::declaration_reference_path_optional(pat.clone()) {
    Some(path) => match crate::v2_std_qualified_name::qualified_name_last_segment(path.clone()) {
    Some(tag) => Rc::new(InferCoproductArmPattern::ArmPatternVariant {
    tag: tag.clone(),
    fields: Rc::new(vec![]),
}),
    std::option::Option::None => Rc::new(InferCoproductArmPattern::ArmPatternUnread),
},
    std::option::Option::None => match crate::v2_std_node_query::construct_tag_path_optional(pat.clone()) {
    std::option::Option::None => Rc::new(InferCoproductArmPattern::ArmPatternUnread),
    Some(path) => match crate::v2_std_qualified_name::qualified_name_last_segment(path.clone()) {
    std::option::Option::None => Rc::new(InferCoproductArmPattern::ArmPatternUnread),
    Some(tag) => Rc::new(InferCoproductArmPattern::ArmPatternVariant {
    tag: tag.clone(),
    fields: crate::std_algebra::skip(pat.children.clone(), 1),
}),
},
},
}
}

pub fn infer_field_pattern_binds(target: Rc<Node>) -> Option<std::string::String> {
    match crate::v2_std_qualified_name::lexical_reference_label_optional(target.clone()) {
    Some(label) => crate::std_optional::optional_present(label.clone()),
    std::option::Option::None => match (*target.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: id, .. } => if (((target.children.clone().len() as i64) == 0) && (id.clone() != crate::v2_std_node_query::pattern_wildcard_name())) {
        crate::std_optional::optional_present(id.clone())
    } else {
        crate::std_optional::optional_absent()
    },
    _ => std::option::Option::None,
} },
    NodeKind::ComputationNode { behavior: _, .. } => std::option::Option::None,
},
}
}

pub fn infer_field_pattern_is_wildcard(target: Rc<Node>) -> bool {
    match (*target.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: id, .. } => (id.clone() == crate::v2_std_node_query::pattern_wildcard_name()),
    _ => false,
} },
    NodeKind::ComputationNode { behavior: _, .. } => false,
}
}

