#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferCoproductArmRow {
    pub covers: Rc<InferCoproductArmCoverage>,
    pub body: Rc<Node>,
    pub arm: Rc<Node>,
    pub catch_all_binder: bool,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum InferCoproductArmCoverage {
    CoversVariant {
        tag: Symbol,
    },
    CoversAll,
}
impl InferCoproductArmCoverage {
    pub fn tag(&self) -> Symbol {
        match self {
            InferCoproductArmCoverage::CoversVariant { tag: __val, .. } => __val.clone(),
            InferCoproductArmCoverage::CoversAll => panic!("no tag on unit variant"),
        }
    }
}

pub fn infer_coproduct_arm_fields_check(pat: Rc<Node>, payload: Rc<Node>, fields: Rc<Vec<Rc<Edge>>>) -> Rc<Outcome<bool>> {
    fields.iter().cloned().fold(Rc::new(Outcome::Accepted {
    value: true,
    diagnostics: Box::new(std::option::Option::None),
}), |acc: Rc<Outcome<bool>>, e: Rc<Edge>| match (*acc.clone()).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { .. } => match (*e.label.clone()).clone() {
    EdgeLabel::Positional => crate::v2_std_diagnostic::outcome_rejected(infer_match_pattern_unread_diagnostic(pat.clone())),
    EdgeLabel::StructuralLabel { label: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_match_pattern_unread_diagnostic(pat.clone())),
    EdgeLabel::Authored { name: field, .. } => match infer_conj_named_type_for_binding(payload.clone(), field.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_match_pattern_field_not_declared_diagnostic(pat.clone())),
    Some(_) => match infer_field_pattern_binds(e.target.clone()) {
    Some(_) => acc.clone(),
    std::option::Option::None => if infer_field_pattern_is_wildcard(e.target.clone()) {
        acc.clone()
    } else {
        crate::v2_std_diagnostic::outcome_rejected(infer_match_pattern_unread_diagnostic(e.target.clone()))
    },
},
},
},
})
}

pub fn infer_coproduct_arm_row(arm: Rc<Node>, coproduct: Rc<InferMatchCoproduct>) -> Rc<Outcome<Rc<InferCoproductArmRow>>> {
    match (*crate::v2_std_node_query::find_core_child(arm.clone(), Rc::new(CoreEdgeLabel::MatchArmPatternEdge))).clone() {
    Outcome::Rejected { diagnostics: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
    Outcome::Accepted { value: pat, .. } => match (*crate::v2_std_node_query::find_core_child(arm.clone(), Rc::new(CoreEdgeLabel::MatchArmBodyEdge))).clone() {
    Outcome::Rejected { diagnostics: _, .. } => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(arm.clone())),
    Outcome::Accepted { value: body, .. } => match (*infer_coproduct_arm_pattern(pat.clone())).clone() {
    InferCoproductArmPattern::ArmPatternUnread => crate::v2_std_diagnostic::outcome_rejected(infer_match_pattern_unread_diagnostic(pat.clone())),
    InferCoproductArmPattern::ArmPatternWildcard => crate::v2_std_diagnostic::outcome_accepted(Rc::new(InferCoproductArmRow {
    covers: Rc::new(InferCoproductArmCoverage::CoversAll),
    body: body.clone(),
    arm: arm.clone(),
    catch_all_binder: false,
})),
    InferCoproductArmPattern::ArmPatternBinder { name: _, .. } => crate::v2_std_diagnostic::outcome_accepted(Rc::new(InferCoproductArmRow {
    covers: Rc::new(InferCoproductArmCoverage::CoversAll),
    body: body.clone(),
    arm: arm.clone(),
    catch_all_binder: true,
})),
    InferCoproductArmPattern::ArmPatternVariant { tag, fields, .. } => match infer_match_variant_payload(coproduct.variants.clone(), tag.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_match_pattern_variant_not_declared_diagnostic(arm.clone())),
    Some(payload) => crate::v2_std_diagnostic::bind_outcome(infer_coproduct_arm_fields_check(pat.clone(), payload.clone(), fields.clone()), |_checked| crate::v2_std_diagnostic::outcome_accepted(Rc::new(InferCoproductArmRow {
    covers: Rc::new(InferCoproductArmCoverage::CoversVariant {
    tag: tag.clone(),
}),
    body: body.clone(),
    arm: arm.clone(),
    catch_all_binder: false,
}))),
},
},
},
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferArmBodyTypes {
    pub derived: Option<Rc<Node>>,
    pub mismatch: bool,
    pub underived: Box<Option<Rc<NonEmptyDiagnostics>>>,
}

pub fn infer_arm_body_type_read(row: Rc<InferCoproductArmRow>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, resolved: Rc<ResolvedTree>) -> Option<Rc<Node>> {
    match lookup_inferred_facts_in_entries(entries.clone(), row.body.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(facts) => match (*infer_branch_operand_resolved_type_with_entries(row.body.clone(), facts.clone(), entries.clone(), instances, resolved)).clone() {
    Witness::Holds { value: t, .. } => Some(t.clone()),
    Witness::Violates { diagnostic: _, .. } => std::option::Option::None,
},
}
}

pub fn infer_arm_declaring_type(rows: Rc<Vec<Rc<InferCoproductArmRow>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, resolved: Rc<ResolvedTree>) -> Option<Rc<Node>> {
    infer_declaring_among(rows.iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<Node>>>, row: Rc<InferCoproductArmRow>| match infer_arm_body_type_read(row.clone(), entries.clone(), instances.clone(), resolved.clone()) {
    std::option::Option::None => acc.clone(),
    Some(t) => crate::std_algebra::list_snoc_item(acc.clone(), t.clone()),
}))
}

pub fn infer_declaring_among(types: Rc<Vec<Rc<Node>>>) -> Option<Rc<Node>> {
    types.iter().cloned().fold(std::option::Option::None, |acc: Option<Rc<Node>>, t: Rc<Node>| match acc.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => if infer_type_is_open(t.clone()) {
        std::option::Option::None
    } else {
        Some(t.clone())
    },
})
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferArmTypesJoin {
    ArmTypesJoined {
        joined: Rc<Node>,
    },
    ArmTypesNoneDeclare,
    ArmTypesConflict,
}
impl InferArmTypesJoin {
    pub fn joined(&self) -> Rc<Node> {
        match self {
            InferArmTypesJoin::ArmTypesJoined { joined: __val, .. } => __val.clone(),
            InferArmTypesJoin::ArmTypesNoneDeclare => panic!("no joined on unit variant"),
            InferArmTypesJoin::ArmTypesConflict => panic!("no joined on unit variant"),
        }
    }
}

pub fn infer_join_arm_types(first: Rc<Node>, second: Rc<Node>, expected: Option<Rc<Node>>, resolved: Rc<ResolvedTree>) -> Rc<InferArmTypesJoin> {
    {
        let first_open = infer_type_is_open(first.clone());
let second_open = infer_type_is_open(second.clone());
let any_open = (first_open.clone() || second_open.clone());
let declaring = infer_join_declaring_at_expected(infer_declaring_among(Rc::new(vec![first.clone(), second.clone()])), any_open.clone(), expected);
if infer_match_no_arm_declares(any_open.clone(), declaring.clone()) {
            Rc::new(InferArmTypesJoin::ArmTypesNoneDeclare)
        } else {
            match declaring.clone() {
    std::option::Option::None => Rc::new(InferArmTypesJoin::ArmTypesJoined {
    joined: first.clone(),
}),
    Some(_) => {
                let a = infer_arm_type_closed_at(first.clone(), declaring.clone(), resolved.clone());
let b = infer_arm_type_closed_at(second.clone(), declaring.clone(), resolved.clone());
if infer_closed_arm_types_agree(a.clone(), b, resolved.clone()) {
                    Rc::new(InferArmTypesJoin::ArmTypesJoined {
    joined: a.clone(),
})
                } else {
                    Rc::new(InferArmTypesJoin::ArmTypesConflict)
                }
},
}
        }
}
}

pub fn infer_join_declaring_at_expected(declaring: Option<Rc<Node>>, any_open: bool, expected: Option<Rc<Node>>) -> Option<Rc<Node>> {
    if any_open.clone() {
        match expected.clone() {
    Some(e) => Some(e.clone()),
    std::option::Option::None => declaring,
}
    } else {
        declaring
    }
}

pub fn infer_arm_type_closed_at(t: Rc<Node>, declaring: Option<Rc<Node>>, resolved: Rc<ResolvedTree>) -> Rc<Node> {
    match declaring.clone() {
    std::option::Option::None => t.clone(),
    Some(d) => { let __fm = infer_close_produced_at_declared(d.clone(), t.clone(), Rc::new(vec![]), resolved.resolved_declarations.clone(), resolved.symbol_index.clone()); if __fm.is_empty() { t.clone() } else { let h0 = (*__fm)[0].clone(); let ht: Rc<Vec<_>> = Rc::new(__fm.skip(1)); infer_type_instantiated(t.clone(), Rc::new({ let mut __cons_v = (*ht.clone()).clone(); __cons_v.insert(0, h0.clone()); __cons_v })) } },
}
}

pub fn infer_type_is_open(t: Rc<Node>) -> bool {
    !crate::std_algebra::is_empty(infer_produced_open_type_params(t))
}

pub fn infer_coproduct_any_open(rows: Rc<Vec<Rc<InferCoproductArmRow>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, resolved: Rc<ResolvedTree>) -> bool {
    rows.iter().cloned().fold(false, |any: bool, row: Rc<InferCoproductArmRow>| (any || match infer_arm_body_type_read(row.clone(), entries.clone(), instances.clone(), resolved.clone()) {
    std::option::Option::None => false,
    Some(t) => infer_type_is_open(t.clone()),
}))
}

pub fn infer_match_no_arm_declares(any_open: bool, declaring: Option<Rc<Node>>) -> bool {
    (any_open.clone() && match declaring.clone() {
    std::option::Option::None => true,
    Some(_) => false,
})
}

pub fn infer_closed_arm_types_agree(a: Rc<Node>, b: Rc<Node>, resolved: Rc<ResolvedTree>) -> bool {
    crate::v2_std_node::node_equal_ignoring_provenance(infer_type_alias_normalized_at(a, resolved.resolved_declarations.clone(), resolved.symbol_index.clone()), infer_type_alias_normalized_at(b, resolved.resolved_declarations.clone(), resolved.symbol_index.clone()))
}

pub fn infer_coproduct_arm_body_types(rows: Rc<Vec<Rc<InferCoproductArmRow>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, declaring: Option<Rc<Node>>, resolved: Rc<ResolvedTree>) -> Rc<InferArmBodyTypes> {
    rows.iter().cloned().fold(Rc::new(InferArmBodyTypes {
    derived: std::option::Option::None,
    mismatch: false,
    underived: Box::new(std::option::Option::None),
}), |acc: Rc<InferArmBodyTypes>, row: Rc<InferCoproductArmRow>| {
        let body_type = match infer_arm_body_type_read(row.clone(), entries.clone(), instances.clone(), resolved.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(t) => Some(infer_arm_type_closed_at(t.clone(), declaring.clone(), resolved.clone())),
};
match body_type.clone() {
    std::option::Option::None => Rc::new(InferArmBodyTypes {
    derived: acc.derived.clone(),
    mismatch: acc.mismatch.clone(),
    underived: Box::new(crate::v2_std_diagnostic::diagnostics_merge((*acc.underived).clone(), Some(crate::v2_std_diagnostic::diagnostics_singleton(infer_match_arm_body_type_underived_diagnostic(row.body.clone()))))),
}),
    Some(t) => match acc.derived.clone() {
    std::option::Option::None => Rc::new(InferArmBodyTypes {
    derived: Some(t.clone()),
    mismatch: acc.mismatch.clone(),
    underived: Box::new((*acc.underived).clone()),
}),
    Some(held) => Rc::new(InferArmBodyTypes {
    derived: acc.derived.clone(),
    mismatch: (acc.mismatch.clone() || !infer_closed_arm_types_agree(held.clone(), t.clone(), resolved.clone())),
    underived: Box::new((*acc.underived).clone()),
}),
},
}
})
}

pub fn infer_match_frontier(node: Rc<Node>, cd: Option<Rc<NonEmptyDiagnostics>>, advisories: Option<Rc<NonEmptyDiagnostics>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome(inferred_facts_not_derived(node.clone(), NotDerivedSite::MatchFrontier, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), |facts| Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(crate::v2_std_diagnostic::diagnostics_merge(cd.clone(), advisories.clone())),
})),
}
}

pub fn infer_match_coproduct_rows(node: Rc<Node>, arms: Rc<Vec<Rc<Node>>>, coproduct: Rc<InferMatchCoproduct>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>, scrutinee_target: Rc<Node>, cd: Option<Rc<NonEmptyDiagnostics>>, expected: Option<Rc<Node>>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*arms.iter().cloned().fold(Rc::new(Outcome::Accepted {
    value: Rc::new(vec![]),
    diagnostics: Box::new(std::option::Option::None),
}), |acc: _, arm: Rc<Node>| match (*acc).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: rows, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); match (*infer_coproduct_arm_row(arm.clone(), coproduct.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: row, .. } => Rc::new(Outcome::Accepted {
    value: crate::std_algebra::list_snoc_item(rows.clone(), row.clone()),
    diagnostics: Box::new(d.clone()),
}),
} },
})).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: rows, .. } => match infer_coproduct_arm_after_catch_all(rows.clone()) {
    Some(unreachable) => crate::v2_std_diagnostic::outcome_rejected(infer_match_arm_unreachable_diagnostic(unreachable.clone())),
    std::option::Option::None => match infer_coproduct_catch_all_binder_widening_over_a_nullary(rows.clone(), coproduct.clone()) {
    Some(binder_arm) => crate::v2_std_diagnostic::outcome_rejected(infer_match_catch_all_binder_widens_over_a_nullary_diagnostic(binder_arm.clone())),
    std::option::Option::None => match (*infer_coproduct_coverage_obligation(node.clone(), scrutinee_target, coproduct.clone(), rows.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { .. } => {
        let any_open = infer_coproduct_any_open(rows.clone(), entries.clone(), coproduct.instances.clone(), resolved.clone());
let declaring = infer_join_declaring_at_expected(infer_arm_declaring_type(rows.clone(), entries.clone(), coproduct.instances.clone(), resolved.clone()), any_open.clone(), expected.clone());
let bodies = infer_coproduct_arm_body_types(rows.clone(), entries.clone(), coproduct.instances.clone(), declaring.clone(), resolved.clone());
let at_expected = infer_match_arms_refusal_at_expected(node.clone(), infer_coproduct_row_bodies(rows.clone()), entries.clone(), expected.clone(), resolved.clone(), rigid_binders);
match at_expected.clone() {
    Some(r) => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    std::option::Option::None => if infer_match_no_arm_declares(any_open.clone(), declaring.clone()) {
            crate::v2_std_diagnostic::outcome_rejected(infer_no_arm_declares_a_type_diagnostic(node.clone()))
        } else {
            if bodies.mismatch.clone() {
                crate::v2_std_diagnostic::outcome_rejected(infer_match_arm_type_mismatch_diagnostic(node.clone()))
            } else {
                match (*bodies.underived).clone() {
    Some(_) => infer_match_frontier(node.clone(), cd.clone(), (*bodies.underived).clone()),
    std::option::Option::None => match bodies.derived.clone() {
    std::option::Option::None => infer_match_frontier(node.clone(), cd.clone(), std::option::Option::None),
    Some(t) => match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome(inferred_facts_from_derived_type(node.clone(), t.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), |facts| Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(cd.clone()),
})),
},
},
}
            }
        },
}
},
},
},
},
}
}

pub fn infer_coproduct_catch_all_binder_widening_over_a_nullary(rows: Rc<Vec<Rc<InferCoproductArmRow>>>, coproduct: Rc<InferMatchCoproduct>) -> Option<Rc<Node>> {
    {
        let walked = rows.iter().cloned().fold(Rc::new(InferBinderRemainderWalk {
    earlier: Rc::new(vec![]),
    found: std::option::Option::None,
}), |acc: Rc<InferBinderRemainderWalk>, row: Rc<InferCoproductArmRow>| match acc.found.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => if (row.catch_all_binder.clone() && infer_remainder_widens_over_a_nullary(coproduct.variants.clone(), acc.earlier.clone())) {
            Rc::new(InferBinderRemainderWalk {
    earlier: acc.earlier.clone(),
    found: Some(row.arm.clone()),
})
        } else {
            match (*row.covers.clone()).clone() {
    InferCoproductArmCoverage::CoversVariant { tag: t, .. } => Rc::new(InferBinderRemainderWalk {
    earlier: crate::std_algebra::list_snoc_item(acc.earlier.clone(), t.clone()),
    found: std::option::Option::None,
}),
    InferCoproductArmCoverage::CoversAll => acc.clone(),
}
        },
});
walked.found.clone()
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferBinderRemainderWalk {
    pub earlier: Rc<Vec<Symbol>>,
    pub found: Option<Rc<Node>>,
}

pub fn infer_remainder_widens_over_a_nullary(variants: Rc<Node>, earlier: Rc<Vec<Symbol>>) -> bool {
    {
        let left = variants.children.clone().iter().cloned().fold(InferRemainderTally {
    alternatives: 0,
    nullary: false,
}, |acc: InferRemainderTally, e: Rc<Edge>| match (*e.label.clone()).clone() {
    EdgeLabel::Authored { name: tag, .. } => if crate::std_algebra::contains(earlier.clone(), tag.clone(), |x, y| (x.clone() == y.clone())) {
            acc.clone()
        } else {
            InferRemainderTally {
    alternatives: v1_rt::int_add(acc.alternatives.clone(), 1),
    nullary: (acc.nullary.clone() || infer_empty_product_shape(e.target.clone())),
}
        },
    EdgeLabel::StructuralLabel { label: _, .. } => acc.clone(),
    EdgeLabel::Positional => acc.clone(),
});
((left.alternatives.clone() >= 2) && left.nullary.clone())
}
}

#[derive(Debug, Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct InferRemainderTally {
    pub alternatives: i64,
    pub nullary: bool,
}

pub fn infer_match_catch_all_binder_widens_over_a_nullary_diagnostic(arm: Rc<Node>) -> Rc<Diagnostic> {
    Rc::new(Diagnostic {
    reason: "infer_match_catch_all_binder_widens_over_a_nullary_variant".to_string(),
    at: crate::v2_std_diagnostic::node_locus(arm),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})
}

pub fn infer_coproduct_arm_after_catch_all(rows: Rc<Vec<Rc<InferCoproductArmRow>>>) -> Option<Rc<Node>> {
    {
        let walked = rows.iter().cloned().fold(Rc::new(InferCatchAllWalk {
    seen: false,
    unreachable: std::option::Option::None,
}), |acc: Rc<InferCatchAllWalk>, row: Rc<InferCoproductArmRow>| match acc.unreachable.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => if acc.seen.clone() {
            Rc::new(InferCatchAllWalk {
    seen: true,
    unreachable: Some(row.arm.clone()),
})
        } else {
            match (*row.covers.clone()).clone() {
    InferCoproductArmCoverage::CoversAll => Rc::new(InferCatchAllWalk {
    seen: true,
    unreachable: std::option::Option::None,
}),
    InferCoproductArmCoverage::CoversVariant { tag: _, .. } => acc.clone(),
}
        },
});
walked.unreachable.clone()
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferCatchAllWalk {
    pub seen: bool,
    pub unreachable: Option<Rc<Node>>,
}

pub fn infer_match_arm_unreachable_diagnostic(arm: Rc<Node>) -> Rc<Diagnostic> {
    Rc::new(Diagnostic {
    reason: "infer_match_arm_unreachable".to_string(),
    at: crate::v2_std_diagnostic::node_locus(arm),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})
}

pub fn infer_uninhabited_match_expected_type_absent_diagnostic(node: Rc<Node>) -> Rc<Diagnostic> {
    Rc::new(Diagnostic {
    reason: "infer_uninhabited_match_expected_type_absent".to_string(),
    at: crate::v2_std_diagnostic::node_locus(node),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::ExternalContractUnknown),
}),
})
}

pub fn infer_uninhabited_match_facts(node: Rc<Node>, expected: Option<Rc<Node>>, descent_proof: Rc<TerminationProof>, cd: Option<Rc<NonEmptyDiagnostics>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match expected.clone() {
    Some(t) => crate::v2_std_diagnostic::bind_outcome(inferred_facts_from_derived_type(node.clone(), t.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), |facts| Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(cd.clone()),
})),
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_uninhabited_match_expected_type_absent_diagnostic(node.clone())),
}
}

pub fn infer_match_coproduct(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>, expected: Option<Rc<Node>>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    if !crate::v2_std_node::all_edges_positional(node.children.clone()) {
        crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(node.clone()))
    } else {
        match crate::v2_std_node::match_slot_target(node.clone(), MatchSlot::MatchScrutineeSlot) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_match_shape_invalid_diagnostic(node.clone())),
    Some(scrutinee_target) => {
            let arms = crate::std_algebra::list_map(crate::v2_std_node::match_role_slots(node.clone(), MatchSlot::MatchArmSlot), |a| crate::v2_std_node::child_slot_target(a));
match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match lookup_inferred_facts_in_entries(entries.clone(), scrutinee_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(scrutinee_target.clone())),
    Some(scrutinee_facts) => match (*infer_branch_operand_resolved_type_with_entries(scrutinee_target.clone(), scrutinee_facts.clone(), entries.clone(), infer_no_type_variable_instances(), resolved.clone())).clone() {
    Witness::Violates { diagnostic: _, .. } => infer_match_frontier(node.clone(), cd.clone(), Some(crate::v2_std_diagnostic::diagnostics_singleton(infer_match_scrutinee_type_underived_diagnostic(scrutinee_target.clone())))),
    Witness::Holds { value: scrutinee_type, .. } => match (*infer_match_coproduct_of_type(scrutinee_type.clone(), resolved.clone())).clone() {
    InferMatchCoproductRead::CoproductNotDeclared => crate::v2_std_diagnostic::outcome_rejected(infer_match_scrutinee_not_coproduct_diagnostic(scrutinee_target.clone())),
    InferMatchCoproductRead::CoproductArityMismatch => crate::v2_std_diagnostic::outcome_rejected(infer_match_type_argument_arity_mismatch_diagnostic(scrutinee_target.clone())),
    InferMatchCoproductRead::UninhabitedScrutinee => if crate::std_algebra::is_empty(arms.clone()) {
                match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => infer_uninhabited_match_facts(node.clone(), expected.clone(), descent_proof.clone(), cd.clone()),
}
            } else {
                crate::v2_std_diagnostic::outcome_rejected(infer_match_scrutinee_not_coproduct_diagnostic(scrutinee_target.clone()))
            },
    InferMatchCoproductRead::CoproductRead { coproduct: coproduct, .. } => infer_match_coproduct_rows(node.clone(), arms.clone(), coproduct.clone(), entries.clone(), resolved.clone(), scrutinee_target.clone(), cd.clone(), expected.clone(), rigid_binders),
},
},
} },
}
},
}
    }
}

pub fn infer_loop_iteration_fold_child_targets(node: Rc<Node>) -> Rc<Vec<Rc<Node>>> {
    {
        let collection_fold = infer_loop_takes_collection_member(node.clone());
node.children.clone().iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<Node>>>, e: Rc<Edge>| if crate::v2_std_node::loop_edge_contributes_to_iteration_fold(node.clone(), e.clone()) {
            if collection_fold.clone() {
                match crate::v2_compiler_fold_lowering::fold_step_body_node(e.target.clone()) {
    Some(body) => crate::std_algebra::list_snoc_item(acc.clone(), body.clone()),
    std::option::Option::None => crate::std_algebra::list_snoc_item(acc.clone(), e.target.clone()),
}
            } else {
                crate::std_algebra::list_snoc_item(acc.clone(), e.target.clone())
            }
        } else {
            acc.clone()
        })
}
}

pub fn infer_loop_body_type_at(target: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Rc<Outcome<Rc<Node>>> {
    match lookup_inferred_facts_in_entries(entries, target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(target.clone())),
    Some(facts) => match (*infer_branch_operand_resolved_type(target.clone(), facts.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    Witness::Holds { value: body_type, .. } => Rc::new(Outcome::Accepted {
    value: body_type.clone(),
    diagnostics: Box::new(std::option::Option::None),
}),
},
}
}

pub fn infer_loop_fixpoint_carrier(node: Rc<Node>, body_targets: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Rc<Outcome<Rc<Node>>> {
    match v1_rt::list_get_optional(&body_targets, 0) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_loop_shape_invalid_diagnostic(node)),
    Some(first_body) => crate::v2_std_diagnostic::bind_outcome(infer_loop_body_type_at(first_body.clone(), entries.clone()), |carrier| body_targets.iter().cloned().fold(Rc::new(Outcome::Accepted {
    value: carrier.clone(),
    diagnostics: Box::new(std::option::Option::None),
}), |acc: Rc<Outcome<_>>, target: Rc<Node>| match (*acc.clone()).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: c, .. } => match (*infer_loop_body_type_at(target.clone(), entries.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: t, .. } => if infer_branch_type_atoms_equal(c.clone(), t.clone()) {
        acc.clone()
    } else {
        crate::v2_std_diagnostic::outcome_rejected(infer_loop_iteration_type_mismatch_diagnostic(target.clone()))
    },
},
})),
}
}

pub fn infer_loop_iteration(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_loop_fixpoint_carrier(node.clone(), infer_loop_iteration_fold_child_targets(node.clone()), entries)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: carrier, diagnostics: ref __rc_diagnostics, .. } => { let ud = __rc_diagnostics.as_ref(); match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome(inferred_facts_from_derived_type(node.clone(), carrier.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), |facts| Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(crate::v2_std_diagnostic::diagnostics_merge(cd.clone(), ud.clone())),
})),
} },
} },
}
}

pub fn infer_operator_algebra_field(op_node: Rc<Node>) -> Option<std::string::String> {
    if infer_operator_is_plus_token(op_node.clone()) {
        infer_canonical_operation_field(crate::v2_std_compilers_target_model::canonical_operation_op_add())
    } else {
        infer_wire_algebra_field(op_node.clone())
    }
}

pub fn infer_operator_is_plus_token(op_node: Rc<Node>) -> bool {
    match crate::v2_std_grammar::node_atom_identity_optional(op_node) {
    Some(id) => (id.clone() == "dag_token_plus".to_string()),
    std::option::Option::None => false,
}
}

pub fn infer_wire_algebra_field(wire: Rc<Node>) -> Option<std::string::String> {
    match (*crate::v2_std_compilers_target_model::canonical_operation_from_wire_node(wire)).clone() {
    Outcome::Accepted { value: decoded, .. } => infer_canonical_operation_field(decoded.clone()),
    Outcome::Rejected { diagnostics: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn infer_canonical_operation_field(operation: Rc<CanonicalOperation>) -> Option<std::string::String> {
    match (*operation.clone()).clone() {
    CanonicalOperation::AlgebraPrimitive { algebra_field: field, .. } => crate::std_optional::optional_present(field.clone()),
    CanonicalOperation::AlgebraInverseCompose { .. } => crate::std_optional::optional_absent(),
    CanonicalOperation::OrderingComparison { compare_field: field, .. } => crate::std_optional::optional_present(field.clone()),
    CanonicalOperation::EqualityComparison { eq_field: field, .. } => crate::std_optional::optional_present(field.clone()),
    CanonicalOperation::CoercionCrossing { homomorphism_rule: _, .. } => crate::std_optional::optional_absent(),
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferAlgebraFieldResult {
    AlgebraFieldResultType {
        result: Rc<Node>,
    },
    AlgebraFieldNotCarried,
    AlgebraFieldRowMalformed {
        cause: Symbol,
    },
}

pub fn infer_algebra_field_result_type(rows: Rc<Vec<Rc<AlgebraInhabitanceDecl>>>, operand_type: Rc<Node>, field: std::string::String, arity: i64) -> Rc<InferAlgebraFieldResult> {
    rows.iter().cloned().fold(Rc::new(InferAlgebraFieldResult::AlgebraFieldNotCarried), |acc: Rc<InferAlgebraFieldResult>, decl: Rc<AlgebraInhabitanceDecl>| match (*acc.clone()).clone() {
    InferAlgebraFieldResult::AlgebraFieldResultType { result: _, .. } => acc.clone(),
    InferAlgebraFieldResult::AlgebraFieldRowMalformed { cause: _, .. } => acc.clone(),
    InferAlgebraFieldResult::AlgebraFieldNotCarried => match (*crate::v2_std_algebra_structure_signature::algebra_inhabitance_field_reading(decl.algebra.clone(), field.clone())).clone() {
    AlgebraInhabitanceFieldReading::InhabitanceFieldReadMalformed { cause: c, .. } => Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: c.clone(),
}),
    AlgebraInhabitanceFieldReading::InhabitanceFieldRead { carrier, declaration, .. } => if infer_branch_type_atoms_equal(carrier.clone(), operand_type.clone()) {
        match (*declaration.clone()).clone() {
    AlgebraFieldDeclaration::FieldDeclared { field_type: t, .. } => infer_algebra_field_codomain_result(t.clone(), carrier.clone(), operand_type.clone(), arity.clone()),
    AlgebraFieldDeclaration::FieldNotDeclared => Rc::new(InferAlgebraFieldResult::AlgebraFieldNotCarried),
    AlgebraFieldDeclaration::InhabitanceMalformed { cause: c, .. } => Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: c.clone(),
}),
}
    } else {
        Rc::new(InferAlgebraFieldResult::AlgebraFieldNotCarried)
    },
},
})
}

pub fn infer_algebra_field_codomain_result(field_type: Rc<Node>, carrier: Rc<Node>, operand_type: Rc<Node>, arity: i64) -> Rc<InferAlgebraFieldResult> {
    match (*crate::v2_std_algebra_structure_signature::algebra_field_operation_type(field_type)).clone() {
    AlgebraFieldDeclaration::InhabitanceMalformed { cause: c, .. } => Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: c.clone(),
}),
    AlgebraFieldDeclaration::FieldNotDeclared => Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: "algebra_field_structure_declares_no_operation".to_string(),
}),
    AlgebraFieldDeclaration::FieldDeclared { field_type: op, .. } => match infer_operator_arrow(op.clone()) {
    std::option::Option::None => Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: "algebra_field_type_not_an_arrow".to_string(),
}),
    Some(arrow) => match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(arrow.clone()), 1) {
    std::option::Option::None => Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: "algebra_field_type_not_an_arrow".to_string(),
}),
    Some(codomain) => match infer_algebra_field_declared_arity(arrow.clone()) {
    std::option::Option::None => Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: "algebra_field_domain_unreadable".to_string(),
}),
    Some(declared_arity) => if (declared_arity.clone() != arity.clone()) {
        Rc::new(InferAlgebraFieldResult::AlgebraFieldRowMalformed {
    cause: "infer_operator_arity_mismatch".to_string(),
})
    } else {
        if infer_branch_type_atoms_equal(codomain.clone(), carrier) {
            Rc::new(InferAlgebraFieldResult::AlgebraFieldResultType {
    result: operand_type.clone(),
})
        } else {
            Rc::new(InferAlgebraFieldResult::AlgebraFieldResultType {
    result: codomain.clone(),
})
        }
    },
},
},
},
}
}

pub fn infer_algebra_field_declared_arity(arrow: Rc<Node>) -> Option<i64> {
    match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(arrow), 0) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(domain) => match infer_formals_from_domain(domain.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(formals) => crate::std_optional::optional_present(crate::std_algebra::length(formals.clone())),
},
}
}

pub fn infer_transform_is_binary_infix_algebra_shape(node: Rc<Node>) -> bool {
    {
        let positional_targets = crate::v2_std_node::positional_child_target_nodes(node.clone());
if (!crate::v2_std_node::all_edges_positional(node.children.clone()) || (crate::std_algebra::length(positional_targets.clone()) != 3)) {
            false
        } else {
            match v1_rt::list_get_optional(&positional_targets, 0) {
    std::option::Option::None => false,
    Some(op_target) => match infer_operator_algebra_field(op_target.clone()) {
    Some(_) => true,
    std::option::Option::None => false,
},
}
        }
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferOperandJudgment {
    OperandsOneType {
        operand_type: Rc<Node>,
    },
    OperandsDisagree {
        diagnostic: Rc<Diagnostic>,
    },
    OperandsNotJudged {
        diagnostic: Rc<Diagnostic>,
    },
}

pub fn infer_unify_transform_operand_types(left_node: Rc<Node>, left_facts: Rc<InferredFacts>, right_node: Rc<Node>, right_facts: Rc<InferredFacts>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>) -> Rc<InferOperandJudgment> {
    match (*infer_branch_operand_resolved_type_with_entries(left_node.clone(), left_facts, entries.clone(), infer_no_type_variable_instances(), resolved.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(InferOperandJudgment::OperandsNotJudged {
    diagnostic: d.clone(),
}),
    Witness::Holds { value: left_type, .. } => match (*infer_branch_operand_resolved_type_with_entries(right_node.clone(), right_facts, entries.clone(), infer_no_type_variable_instances(), resolved.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(InferOperandJudgment::OperandsNotJudged {
    diagnostic: d.clone(),
}),
    Witness::Holds { value: right_type, .. } => if infer_branch_type_atoms_equal(left_type.clone(), right_type.clone()) {
        Rc::new(InferOperandJudgment::OperandsOneType {
    operand_type: left_type.clone(),
})
    } else {
        if (infer_operand_literal_elaborates_at(right_node.clone(), left_type.clone(), resolved.clone()) || infer_operand_literal_elaborates_at(left_node.clone(), right_type.clone(), resolved.clone())) {
            Rc::new(InferOperandJudgment::OperandsNotJudged {
    diagnostic: infer_transform_operand_type_mismatch_diagnostic(left_node.clone()),
})
        } else {
            Rc::new(InferOperandJudgment::OperandsDisagree {
    diagnostic: infer_transform_operand_type_mismatch_diagnostic(left_node.clone()),
})
        }
    },
},
}
}

pub fn infer_operand_literal_elaborates_at(literal_node: Rc<Node>, expected: Rc<Node>, resolved: Rc<ResolvedTree>) -> bool {
    match (*infer_literal_elaborates_at(literal_node, expected, resolved.resolved_declarations.clone(), resolved.symbol_index.clone())).clone() {
    InferLiteralElaboration::InferLiteralElaboratesTo { destination_type: _, .. } => true,
    InferLiteralElaboration::InferLiteralNotElaborated => false,
    InferLiteralElaboration::InferLiteralElaborationRefused { cause: _, .. } => false,
}
}

pub fn infer_comparison_not_derived(node: Rc<Node>, od: Option<Rc<NonEmptyDiagnostics>>) -> Rc<Outcome<Rc<InferredFacts>>> {
    match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome_accepted(od, inferred_facts_not_derived(node.clone(), NotDerivedSite::ComparisonNotDerived, Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
}))),
}
}

pub fn infer_field_is_comparison(field: std::string::String) -> bool {
    ((field.clone() == "equivalence_field_eq".to_string()) || (field.clone() == "ordered_ring_field_compare".to_string()))
}

pub fn infer_operation_result_signature(op_node: Rc<Node>) -> Option<Rc<Node>> {
    if infer_operator_is_plus_token(op_node.clone()) {
        crate::std_optional::optional_absent()
    } else {
        match (*crate::v2_std_compilers_target_model::canonical_operation_from_wire_node(op_node.clone())).clone() {
    Outcome::Rejected { diagnostics: _, .. } => crate::std_optional::optional_absent(),
    Outcome::Accepted { value: decoded, .. } => match (*decoded.clone()).clone() {
    CanonicalOperation::OrderingComparison { .. } => crate::std_optional::optional_present(crate::v2_std_algebra_structure_signature::ordering_predicate_signature_node()),
    CanonicalOperation::AlgebraPrimitive { algebra_field: _, .. } => crate::std_optional::optional_absent(),
    CanonicalOperation::AlgebraInverseCompose { .. } => crate::std_optional::optional_absent(),
    CanonicalOperation::EqualityComparison { .. } => crate::std_optional::optional_absent(),
    CanonicalOperation::CoercionCrossing { homomorphism_rule: _, .. } => crate::std_optional::optional_absent(),
},
}
    }
}

pub fn infer_operation_value_type(op_node: Rc<Node>, answer: Rc<Node>) -> Rc<Outcome<Rc<Node>>> {
    match infer_operation_result_signature(op_node) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_accepted(answer.clone()),
    Some(signature) => infer_apply_result_signature(signature.clone(), answer.clone()),
}
}

pub fn infer_apply_result_signature(signature: Rc<Node>, answer: Rc<Node>) -> Rc<Outcome<Rc<Node>>> {
    {
        let malformed = crate::v2_std_diagnostic::outcome_rejected(Rc::new(Diagnostic {
    reason: "infer_operation_result_signature_malformed".to_string(),
    at: crate::v2_std_diagnostic::node_locus(signature.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
}));
match infer_operator_arrow(signature.clone()) {
    std::option::Option::None => malformed,
    Some(arrow) => {
            let targets = crate::v2_std_node::positional_child_target_nodes(arrow.clone());
match v1_rt::list_get_optional(&targets, 0) {
    std::option::Option::None => malformed,
    Some(domain) => match v1_rt::list_get_optional(&targets, 1) {
    std::option::Option::None => malformed,
    Some(codomain) => match infer_formals_from_domain(domain.clone()) {
    std::option::Option::None => malformed,
    Some(formals) => match v1_rt::list_get_optional(&formals, 0) {
    std::option::Option::None => malformed,
    Some(formal) => if (crate::std_algebra::length(formals.clone()) != 1) {
                malformed
            } else {
                if infer_branch_type_atoms_equal(formal.declared.clone(), answer) {
                    crate::v2_std_diagnostic::outcome_accepted(codomain.clone())
                } else {
                    crate::v2_std_diagnostic::outcome_rejected(Rc::new(Diagnostic {
    reason: "infer_operation_result_signature_domain_mismatch".to_string(),
    at: crate::v2_std_diagnostic::node_locus(signature.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
}))
                }
            },
},
},
},
}
},
}
}
}

pub fn infer_transform_argument_targets(node: Rc<Node>) -> Rc<Vec<Rc<Node>>> {
    crate::std_algebra::skip(crate::v2_std_node::positional_child_target_nodes(node), 1)
}

pub fn infer_operator_arrow(operator: Rc<Node>) -> Option<Rc<Node>> {
    match (*operator.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Arrow => Some(operator.clone()),
    Connective::Atom { identity: _, .. } => std::option::Option::None,
    Connective::Conj => std::option::Option::None,
    Connective::Disj => std::option::Option::None,
    Connective::Instantiation => std::option::Option::None,
} },
    NodeKind::ComputationNode { behavior: _, .. } => std::option::Option::None,
}
}

pub fn infer_formals_from_domain(domain: Rc<Node>) -> Option<Rc<Vec<Rc<InhabitanceFormal>>>> {
    match (*domain.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Conj => domain.children.clone().iter().cloned().fold(Some(Rc::new(vec![])), |acc: Option<Rc<Vec<Rc<InhabitanceFormal>>>>, e: Rc<Edge>| match acc {
    std::option::Option::None => std::option::Option::None,
    Some(formals) => match crate::v2_std_node_query::declared_field_from_edge(e.clone()) {
    Some(binder) => Some(crate::std_algebra::list_snoc_item(formals.clone(), Rc::new(InhabitanceFormal {
    parameter_identity: binder.name.clone(),
    declared: binder.type_node.clone(),
}))),
    std::option::Option::None => std::option::Option::None,
},
}),
    Connective::Atom { identity: _, .. } => std::option::Option::None,
    Connective::Disj => std::option::Option::None,
    Connective::Arrow => std::option::Option::None,
    Connective::Instantiation => std::option::Option::None,
} },
    NodeKind::ComputationNode { behavior: _, .. } => std::option::Option::None,
}
}

pub fn infer_application_callee_use(node: Rc<Node>) -> Option<Rc<Node>> {
    v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(node), 0)
}

pub fn infer_application_callee_arrow_with_facts(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Option<Rc<Node>> {
    match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(node), 0) {
    std::option::Option::None => std::option::Option::None,
    Some(operator) => match infer_operator_arrow(operator.clone()) {
    Some(arrow) => Some(arrow.clone()),
    std::option::Option::None => match lookup_inferred_facts_in_entries(entries, operator.clone()) {
    std::option::Option::None => std::option::Option::None,
    Some(facts) => match (*facts.grounding.clone()).clone() {
    NodeGrounding::GroundingNotDerived { .. } => std::option::Option::None,
    NodeGrounding::GroundingNoValue { node: _, .. } => std::option::Option::None,
    NodeGrounding::DerivedGrounding { grounding: g, .. } => infer_operator_arrow(g.witness.structural.evidence.clone()),
},
},
},
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferApplicationFormals {
    FormalsInDeclaredOrder {
        formals: Rc<Vec<Rc<InhabitanceFormal>>>,
    },
    FormalsUnresolved,
    FormalsOrderRefused {
        reason: Symbol,
    },
}

pub fn infer_application_formals(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Rc<InferApplicationFormals> {
    match infer_application_callee_arrow_with_facts(node, entries) {
    std::option::Option::None => Rc::new(InferApplicationFormals::FormalsUnresolved),
    Some(arrow) => match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(arrow.clone()), 0) {
    std::option::Option::None => Rc::new(InferApplicationFormals::FormalsUnresolved),
    Some(domain) => match infer_formals_from_domain(domain.clone()) {
    std::option::Option::None => Rc::new(InferApplicationFormals::FormalsUnresolved),
    Some(formals) => match (*crate::v2_std_arrow_signature::arrow_declared_parameter_order(arrow.clone())).clone() {
    ArrowParameterOrder::ArrowParameterOrderAbsent => Rc::new(InferApplicationFormals::FormalsOrderRefused {
    reason: crate::v2_std_inhabitance::application_parameter_order_absent_reason(),
}),
    ArrowParameterOrder::ArrowParameterOrderMalformed => Rc::new(InferApplicationFormals::FormalsOrderRefused {
    reason: crate::v2_std_inhabitance::application_parameter_order_malformed_reason(),
}),
    ArrowParameterOrder::ArrowParameterOrderDeclared { labels: labels, .. } => infer_formals_in_declared_order(formals.clone(), labels.clone()),
},
},
},
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct InferIndexedLabel {
    pub label: Symbol,
    pub position: i64,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct InferIndexWalk {
    pub index: i64,
    pub labels: Rc<Vec<Rc<InferIndexedLabel>>>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InferFormalPairing {
    pub indexed: Rc<InferIndexedLabel>,
    pub formal: Rc<InhabitanceFormal>,
}

pub fn infer_formals_in_declared_order(formals: Rc<Vec<Rc<InhabitanceFormal>>>, labels: Rc<Vec<Symbol>>) -> Rc<InferApplicationFormals> {
    if (crate::std_algebra::length(formals.clone()) != crate::std_algebra::length(labels.clone())) {
        Rc::new(InferApplicationFormals::FormalsOrderRefused {
    reason: crate::v2_std_inhabitance::application_parameter_order_malformed_reason(),
})
    } else {
        {
            let indexed = labels.iter().cloned().fold(Rc::new(InferIndexWalk {
    index: 0,
    labels: Rc::new(vec![]),
}), |acc: Rc<InferIndexWalk>, l: Symbol| Rc::new(InferIndexWalk {
    index: v1_rt::int_add(acc.index.clone(), 1),
    labels: Rc::new({ let mut __cons_v = (*acc.labels.clone()).clone(); __cons_v.insert(0, Rc::new(InferIndexedLabel {
    label: l.clone(),
    position: acc.index.clone(),
})); __cons_v }),
})).labels.clone();
let pairs = infer_pair_by_label(Rc::new({ let mut __keyed: Vec<_> = indexed.iter().cloned().map(|__e: Rc<InferIndexedLabel>| { let __k = (infer_indexed_label_key)(__e.clone()); (__k, __e) }).collect(); __keyed.sort_by(|__x, __y| v1_rt::canonical_key_cmp(&__x.0, &__y.0)); __keyed.into_iter().map(|(_, __e)| __e).collect::<Vec<_>>() }), Rc::new({ let mut __keyed: Vec<_> = formals.iter().cloned().map(|__e: Rc<InhabitanceFormal>| { let __k = (infer_formal_identity_key)(__e.clone()); (__k, __e) }).collect(); __keyed.sort_by(|__x, __y| v1_rt::canonical_key_cmp(&__x.0, &__y.0)); __keyed.into_iter().map(|(_, __e)| __e).collect::<Vec<_>>() }));
if infer_pairings_match(pairs.clone()) {
                Rc::new(InferApplicationFormals::FormalsInDeclaredOrder {
    formals: infer_pairings_in_declared_order(pairs.clone()),
})
            } else {
                Rc::new(InferApplicationFormals::FormalsOrderRefused {
    reason: crate::v2_std_inhabitance::application_parameter_order_malformed_reason(),
})
            }
}
    }
}

pub fn infer_indexed_label_key(x: Rc<InferIndexedLabel>) -> std::string::String {
    x.label.clone()
}

pub fn infer_formal_identity_key(f: Rc<InhabitanceFormal>) -> std::string::String {
    f.parameter_identity.clone()
}

pub fn infer_pairing_position_key(p: Rc<InferFormalPairing>) -> i64 {
    p.indexed.position.clone()
}

pub fn infer_pair_by_label(labels: Rc<Vec<Rc<InferIndexedLabel>>>, formals: Rc<Vec<Rc<InhabitanceFormal>>>) -> Rc<Vec<Rc<InferFormalPairing>>> {
    crate::std_algebra::zip_map(labels, formals, |il, f| Rc::new(InferFormalPairing {
    indexed: il.clone(),
    formal: f.clone(),
}))
}

pub fn infer_pairings_match(pairs: Rc<Vec<Rc<InferFormalPairing>>>) -> bool {
    pairs.iter().cloned().fold(true, |acc: bool, p: Rc<InferFormalPairing>| (acc && (p.indexed.label.clone() == p.formal.parameter_identity.clone())))
}

pub fn infer_pairings_in_declared_order(pairs: Rc<Vec<Rc<InferFormalPairing>>>) -> Rc<Vec<Rc<InhabitanceFormal>>> {
    crate::std_algebra::list_map(Rc::new({ let mut __keyed: Vec<_> = pairs.iter().cloned().map(|__e: Rc<InferFormalPairing>| { let __k = (infer_pairing_position_key)(__e.clone()); (__k, __e) }).collect(); __keyed.sort_by(|__x, __y| v1_rt::canonical_key_cmp(&__x.0, &__y.0)); __keyed.into_iter().map(|(_, __e)| __e).collect::<Vec<_>>() }), infer_pairing_formal)
}

pub fn infer_pairing_formal(p: Rc<InferFormalPairing>) -> Rc<InhabitanceFormal> {
    p.formal.clone()
}

pub fn infer_application_type_params(node: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>) -> Rc<Vec<Symbol>> {
    match infer_application_callee_arrow_with_facts(node, entries) {
    std::option::Option::None => Rc::new(vec![]),
    Some(arrow) => crate::v2_std_type_binder::type_param_names(arrow.clone()),
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct InhabitanceFormalArg {
    pub formal: Rc<InhabitanceFormal>,
    pub arg: Rc<Node>,
}

pub fn infer_inhabitance_undecidable_accepted(application: Rc<Node>, reason: InhabitanceUndecidableReason) -> Rc<Outcome<bool>> {
    Rc::new(Outcome::Accepted {
    value: true,
    diagnostics: Box::new(Some(crate::v2_std_diagnostic::diagnostics_singleton(crate::v2_std_inhabitance::inhabitance_undecidable_diagnostic(application, reason)))),
})
}

pub fn infer_declared_position_undecidable_reason(declared: Rc<Node>, type_params: Rc<Vec<Symbol>>, rigid_binders: Rc<Vec<Symbol>>) -> Option<InhabitanceUndecidableReason> {
    match infer_type_variable_binder(declared.clone(), type_params.clone()) {
    Some(_) => crate::v2_std_inhabitance::inhabitance_node_undecidable_reason(declared.clone(), type_params.clone()),
    std::option::Option::None => match (*declared.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Atom { identity: _, .. }) => { let Connective::Atom { identity: id, .. } = __rc_connective.as_ref() else { unreachable!() }; if infer_atom_is_rigid_binder_in_scope(id.clone(), rigid_binders) {
        std::option::Option::None
    } else {
        match crate::v2_extdeps_languages_dag::dag_binding_denotation(id.clone()) {
    Some(_) => std::option::Option::None,
    std::option::Option::None => match infer_established_value_type_optional(declared.clone()) {
    Some(_) => std::option::Option::None,
    std::option::Option::None => crate::std_optional::optional_present(crate::v2_std_inhabitance::undecidable_formal_unresolved()),
},
}
    } },
    _ => std::option::Option::None,
},
}
}

pub fn infer_declared_type_denotation(declared: Rc<Node>) -> Rc<Node> {
    crate::v2_std_node::fold_node(declared, Rc::new(NodeFold {
    init: { Rc::new(move |self_| match (*self_.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Atom { identity: _, .. }) => { let Connective::Atom { identity: id, .. } = __rc_connective.as_ref() else { unreachable!() }; match crate::v2_extdeps_languages_dag::dag_binding_denotation(id.clone()) {
    Some(denoted) => denoted.clone(),
    std::option::Option::None => match infer_established_value_type_optional(self_.clone()) {
    Some(established) => established.clone(),
    std::option::Option::None => Rc::new(Node {
    kind: self_.kind.clone(),
    children: Rc::new(vec![]),
    occurrence_id: self_.occurrence_id.clone(),
}),
},
} },
    _ => Rc::new(Node {
    kind: self_.kind.clone(),
    children: Rc::new(vec![]),
    occurrence_id: self_.occurrence_id.clone(),
}),
}) },
    step: { Rc::new(move |acc, edge, sub| Rc::new(Node {
    kind: acc.kind.clone(),
    children: crate::std_algebra::list_snoc_item(acc.children.clone(), Rc::new(Edge {
    label: edge.label.clone(),
    target: sub.clone(),
    declaration: edge.declaration.clone(),
})),
    occurrence_id: acc.occurrence_id.clone(),
})) },
    _phantom: std::marker::PhantomData,
}))
}

pub fn infer_judge_declared_position(position: Rc<DeclaredTypePosition>, application: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>, formal: Rc<InhabitanceFormal>, produced_at: Rc<Node>, type_params: Rc<Vec<Symbol>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<Vec<Rc<TypeVariableInstance>>>>> {
    match infer_declared_position_undecidable_reason(formal.declared.clone(), type_params.clone(), rigid_binders) {
    Some(reason) => match (*infer_inhabitance_undecidable_accepted(application.clone(), reason.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: instances.clone(),
    diagnostics: Box::new(d.clone()),
}) },
},
    std::option::Option::None => match (*infer_literal_elaborates_at(produced_at.clone(), infer_declared_type_denotation(formal.declared.clone()), declarations.clone(), bindings.clone())).clone() {
    InferLiteralElaboration::InferLiteralElaboratesTo { destination_type: _, .. } => Rc::new(Outcome::Accepted {
    value: instances.clone(),
    diagnostics: Box::new(std::option::Option::None),
}),
    InferLiteralElaboration::InferLiteralElaborationRefused { cause: cause, .. } => crate::v2_std_diagnostic::outcome_rejected(Rc::new(Diagnostic {
    reason: cause.clone(),
    at: crate::v2_std_diagnostic::node_locus(produced_at.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})),
    InferLiteralElaboration::InferLiteralNotElaborated => match lookup_inferred_facts_in_entries(entries, produced_at.clone()) {
    std::option::Option::None => match (*infer_inhabitance_undecidable_accepted(application.clone(), crate::v2_std_inhabitance::undecidable_argument_type_not_derived())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: instances.clone(),
    diagnostics: Box::new(d.clone()),
}) },
},
    Some(facts) => match (*inferred_facts_resolved_type(facts.clone())).clone() {
    Witness::Violates { diagnostic: _, .. } => match (*infer_inhabitance_undecidable_accepted(application.clone(), crate::v2_std_inhabitance::undecidable_argument_type_not_derived())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: instances.clone(),
    diagnostics: Box::new(d.clone()),
}) },
},
    Witness::Holds { value: produced, .. } => match infer_node_mention_contested(formal.declared.clone(), bindings.clone()) {
    Some(claimants) => infer_declaration_identity_contested_rejected(application.clone(), claimants.clone()),
    std::option::Option::None => match infer_node_mention_contested(produced.clone(), bindings.clone()) {
    Some(claimants) => infer_declaration_identity_contested_rejected(produced_at.clone(), claimants.clone()),
    std::option::Option::None => {
        let declared_n = infer_type_alias_normalized_at(formal.declared.clone(), declarations.clone(), bindings.clone());
let closed = infer_close_produced_at_declared(declared_n.clone(), produced.clone(), instances.clone(), declarations.clone(), bindings.clone());
let judged = { let __fm = closed.clone(); if __fm.is_empty() { produced.clone() } else { infer_type_instantiated(produced.clone(), closed.clone()) } };
let obligation = infer_declared_type_obligation(position, formal.parameter_identity.clone(), declared_n.clone(), judged, application.clone(), type_params.clone(), declarations.clone(), bindings.clone());
match (*crate::v2_std_inhabitance::declared_type_inhabitance(obligation.clone())).clone() {
    InhabitanceVerdict::Inhabits { homomorphism: _, .. } => Rc::new(Outcome::Accepted {
    value: closed.clone(),
    diagnostics: Box::new(std::option::Option::None),
}),
    InhabitanceVerdict::InhabitanceUndecidable { reason: reason, .. } => match (*infer_inhabitance_undecidable_accepted(obligation.application.clone(), reason.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: closed.clone(),
    diagnostics: Box::new(d.clone()),
}) },
},
    InhabitanceVerdict::InhabitanceRefused { find_witness_reason: fw_reason, .. } => crate::v2_std_diagnostic::outcome_rejected(crate::v2_std_inhabitance::application_argument_does_not_inhabit_diagnostic(obligation.clone(), fw_reason.clone())),
}
},
},
},
},
},
},
}
}

pub fn infer_judge_declared_position_closing(position: Rc<DeclaredTypePosition>, application: Rc<Node>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>, formal: Rc<InhabitanceFormal>, produced_at: Rc<Node>, type_params: Rc<Vec<Symbol>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, rigid_binders: Rc<Vec<Symbol>>) -> Rc<Outcome<Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>>> {
    match (*infer_judge_declared_position(position, application, entries.clone(), declarations, bindings, formal, produced_at.clone(), type_params, instances, rigid_binders)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: closed, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); match (*infer_entries_instantiate_at(entries.clone(), produced_at.clone(), closed.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: next, diagnostics: ref __rc_diagnostics, .. } => { let id = __rc_diagnostics.as_ref(); Rc::new(Outcome::Accepted {
    value: next.clone(),
    diagnostics: Box::new(crate::v2_std_diagnostic::diagnostics_merge(d.clone(), id.clone())),
}) },
} },
}
}

pub fn infer_no_type_variable_instances() -> Rc<Vec<Rc<TypeVariableInstance>>> {
    Rc::new(vec![])
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferFormalMatch {
    InferFormalMatched {
        instances: Rc<Vec<Rc<TypeVariableInstance>>>,
    },
    InferFormalShapeMismatch,
}
impl InferFormalMatch {
    pub fn instances(&self) -> Rc<Vec<Rc<TypeVariableInstance>>> {
        match self {
            InferFormalMatch::InferFormalMatched { instances: __val, .. } => __val.clone(),
            InferFormalMatch::InferFormalShapeMismatch => panic!("no instances on unit variant"),
        }
    }
}

pub fn infer_type_variable_binder(t: Rc<Node>, type_params: Rc<Vec<Symbol>>) -> Option<std::string::String> {
    match (*t.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Atom { identity: id, .. } => if (((t.children.clone().len() as i64) == 0) && type_params.iter().cloned().fold(false, |acc: bool, p: Symbol| (acc || (p.clone() == id.clone())))) {
        crate::std_optional::optional_present(id.clone())
    } else {
        crate::std_optional::optional_absent()
    },
    _ => crate::std_optional::optional_absent(),
} },
    NodeKind::ComputationNode { behavior: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn infer_match_generic_formal(formal: Rc<Node>, produced: Rc<Node>, type_params: Rc<Vec<Symbol>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, declarations: Rc<SymbolIndex>) -> Rc<InferFormalMatch> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match infer_type_variable_binder(formal.clone(), type_params.clone()) {
    Some(binder) => match crate::v2_std_inhabitance::type_variable_instance_lookup(instances.clone(), binder.clone()) {
    Some(_) => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
    std::option::Option::None => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: crate::std_algebra::list_snoc_item(instances.clone(), Rc::new(TypeVariableInstance {
    binder: binder.clone(),
    instance: produced.clone(),
})),
}),
},
    std::option::Option::None => match (*formal.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Instantiation => match (*produced.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Instantiation => {
            let f = infer_type_head_and_args(formal.clone());
let p = infer_type_head_and_args(produced.clone());
if (crate::std_algebra::length(f.args.clone()) != crate::std_algebra::length(p.args.clone())) {
                Rc::new(InferFormalMatch::InferFormalShapeMismatch)
            } else {
                if crate::v2_std_inhabitance::inhabitance_node_mentions_type_variable(f.head.clone(), type_params.clone()) {
                    Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
})
                } else {
                    if !crate::v2_std_node::node_equal_ignoring_provenance(f.head.clone(), p.head.clone()) {
                        Rc::new(InferFormalMatch::InferFormalShapeMismatch)
                    } else {
                        crate::std_algebra::zip_map(f.args.clone(), p.args.clone(), |fa, pa| Rc::new(InferTypePair {
    formal: fa.clone(),
    produced: pa.clone(),
})).iter().cloned().fold(Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}), |acc: Rc<InferFormalMatch>, pair: Rc<InferTypePair>| match (*acc.clone()).clone() {
    InferFormalMatch::InferFormalShapeMismatch => acc.clone(),
    InferFormalMatch::InferFormalMatched { instances: so_far, .. } => infer_match_generic_formal(pair.formal.clone(), pair.produced.clone(), type_params.clone(), so_far.clone(), declarations.clone()),
})
                    }
                }
            }
},
    _ => Rc::new(InferFormalMatch::InferFormalShapeMismatch),
} },
    NodeKind::ComputationNode { behavior: _, .. } => Rc::new(InferFormalMatch::InferFormalShapeMismatch),
},
    Connective::Arrow => match (*produced.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Arrow => infer_match_generic_arrow(formal.clone(), produced.clone(), type_params.clone(), instances.clone(), declarations.clone()),
    _ => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
} },
    NodeKind::ComputationNode { behavior: _, .. } => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
},
    _ => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
} },
    NodeKind::ComputationNode { behavior: _, .. } => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
},
}
    })
}

pub fn infer_arrow_ordered_domain_types(arrow: Rc<Node>) -> Option<Rc<Vec<Rc<Node>>>> {
    match (*crate::v2_std_arrow_signature::arrow_declared_parameter_order(arrow.clone())).clone() {
    ArrowParameterOrder::ArrowParameterOrderAbsent => crate::std_optional::optional_absent(),
    ArrowParameterOrder::ArrowParameterOrderMalformed => crate::std_optional::optional_absent(),
    ArrowParameterOrder::ArrowParameterOrderDeclared { labels: labels, .. } => match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(arrow.clone()), 0) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(domain) => labels.iter().cloned().fold(crate::std_optional::optional_present(Rc::new(vec![])), |acc: _, label: Symbol| match acc.clone() {
    std::option::Option::None => acc.clone(),
    Some(types) => match infer_domain_field_type_named(domain.clone(), label.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(t) => crate::std_optional::optional_present(crate::std_algebra::list_snoc_item(types.clone(), t.clone())),
},
}),
},
}
}

pub fn infer_domain_field_type_named(domain: Rc<Node>, label: std::string::String) -> Option<Rc<Node>> {
    {
        let carrying = domain.children.clone().iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<Node>>>, e: Rc<Edge>| match crate::v2_std_node_query::declared_field_from_edge(e.clone()) {
    Some(field) => if (field.name.clone() == label.clone()) {
            crate::std_algebra::list_snoc_item(acc.clone(), field.type_node.clone())
        } else {
            acc.clone()
        },
    std::option::Option::None => acc.clone(),
});
{ let __fm = carrying.clone(); if __fm.len() >= 1 { let t = (*__fm)[0].clone(); let rest: Rc<Vec<_>> = Rc::new(__fm.skip(1)); if crate::std_algebra::is_empty(rest.clone()) {
            crate::std_optional::optional_present(t.clone())
        } else {
            crate::std_optional::optional_absent()
        } } else { crate::std_optional::optional_absent() } }
}
}

pub fn infer_match_generic_arrow(formal: Rc<Node>, produced: Rc<Node>, type_params: Rc<Vec<Symbol>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, declarations: Rc<SymbolIndex>) -> Rc<InferFormalMatch> {
    match infer_arrow_ordered_domain_types(formal.clone()) {
    std::option::Option::None => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
    Some(formal_inputs) => match infer_arrow_ordered_domain_types(produced.clone()) {
    std::option::Option::None => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
    Some(produced_inputs) => infer_match_generic_arrow_inputs(formal.clone(), produced.clone(), formal_inputs.clone(), produced_inputs.clone(), type_params, instances.clone(), declarations),
},
}
}

pub fn infer_match_generic_arrow_inputs(formal: Rc<Node>, produced: Rc<Node>, formal_inputs: Rc<Vec<Rc<Node>>>, produced_inputs: Rc<Vec<Rc<Node>>>, type_params: Rc<Vec<Symbol>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, declarations: Rc<SymbolIndex>) -> Rc<InferFormalMatch> {
    if (!crate::std_algebra::is_empty(crate::v2_std_type_binder::type_param_names(produced.clone())) || (crate::std_algebra::length(formal_inputs.clone()) != crate::std_algebra::length(produced_inputs.clone()))) {
        Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
})
    } else {
        {
            let inputs = crate::std_algebra::zip_map(formal_inputs.clone(), produced_inputs.clone(), |fa, pa| Rc::new(InferTypePair {
    formal: fa.clone(),
    produced: pa.clone(),
})).iter().cloned().fold(Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}), |acc: Rc<InferFormalMatch>, pair: Rc<InferTypePair>| match (*acc.clone()).clone() {
    InferFormalMatch::InferFormalShapeMismatch => acc.clone(),
    InferFormalMatch::InferFormalMatched { instances: so_far, .. } => infer_match_generic_formal(pair.formal.clone(), pair.produced.clone(), type_params.clone(), so_far.clone(), declarations.clone()),
});
let whole = match (*inputs.clone()).clone() {
    InferFormalMatch::InferFormalShapeMismatch => inputs.clone(),
    InferFormalMatch::InferFormalMatched { instances: so_far, .. } => match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(formal), 1) {
    std::option::Option::None => inputs.clone(),
    Some(formal_codomain) => match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(produced.clone()), 1) {
    std::option::Option::None => inputs.clone(),
    Some(produced_codomain) => infer_match_generic_formal(formal_codomain.clone(), produced_codomain.clone(), type_params.clone(), so_far.clone(), declarations.clone()),
},
},
};
match (*whole.clone()).clone() {
    InferFormalMatch::InferFormalShapeMismatch => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: instances.clone(),
}),
    InferFormalMatch::InferFormalMatched { instances: _, .. } => whole.clone(),
}
}
    }
}

pub fn infer_indexes_lookup(bindings: Rc<SymbolIndex>, bodies: Rc<SymbolIndex>, path: QualifiedName) -> Option<Rc<Node>> {
    match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(bindings, path)).clone() {
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: declaring, .. } => crate::v2_std_symbol_index::symbol_index_lookup(bodies, declaring.clone()),
    MentionDeclaringIdentity::MentionDeclaringUnavailable => crate::std_optional::optional_absent(),
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn infer_resolved_lookup(resolved: Rc<ResolvedTree>, path: QualifiedName) -> Option<Rc<Node>> {
    infer_indexes_lookup(resolved.symbol_index.clone(), resolved.resolved_declarations.clone(), path)
}

pub fn infer_resolved_payload(resolved: Rc<ResolvedTree>, path: QualifiedName) -> Option<DeclaredPayloadKind> {
    match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(resolved.symbol_index.clone(), path)).clone() {
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: declaring, .. } => crate::v2_std_symbol_index::symbol_index_declared_payload_at(resolved.symbol_index.clone(), declaring.clone()),
    MentionDeclaringIdentity::MentionDeclaringUnavailable => crate::std_optional::optional_absent(),
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn infer_type_decl_identity_node(declared: Rc<Node>, identity: QualifiedName) -> Rc<Node> {
    if crate::v2_std_node_query::node_is_coproduct(declared.clone()) {
        declared.clone()
    } else {
        match crate::v2_std_qualified_name::qualified_name_last_segment(identity) {
    std::option::Option::None => declared.clone(),
    Some(leaf) => match (*crate::v2_std_node_query::find_named_child(declared.clone(), leaf.clone())).clone() {
    Outcome::Accepted { value: inner, .. } => inner.clone(),
    Outcome::Rejected { diagnostics: _, .. } => declared.clone(),
},
}
    }
}

pub fn infer_type_alias_stored_at(bindings: Rc<SymbolIndex>, bodies: Rc<SymbolIndex>, path: QualifiedName) -> Option<Rc<Node>> {
    match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(bindings.clone(), path.clone())).clone() {
    MentionDeclaringIdentity::MentionDeclaringUnavailable => crate::std_optional::optional_absent(),
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: _, .. } => crate::std_optional::optional_absent(),
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: _, .. } => infer_indexes_lookup(bindings.clone(), bodies, path.clone()),
}
}

pub fn infer_type_alias_rhs(declared: Rc<Node>, aliased: Rc<Node>, args: Rc<Vec<Rc<Node>>>) -> Option<Rc<Node>> {
    if infer_alias_is_refined(declared.clone(), aliased.clone()) {
        crate::std_optional::optional_absent()
    } else {
        {
            let params = crate::v2_std_type_binder::type_param_names(declared.clone());
if (crate::std_algebra::length(params.clone()) != crate::std_algebra::length(args.clone())) {
                crate::std_optional::optional_absent()
            } else {
                { let __fm = params.clone(); if __fm.is_empty() { crate::std_optional::optional_present(aliased.clone()) } else { crate::std_optional::optional_present(infer_type_instantiated(aliased.clone(), crate::std_algebra::zip_map(params.clone(), args.clone(), |p, a| Rc::new(TypeVariableInstance {
    binder: p.clone(),
    instance: a.clone(),
})))) } }
            }
}
    }
}

pub fn infer_node_mention_contested(t: Rc<Node>, bindings: Rc<SymbolIndex>) -> Option<Rc<FreeMonoid<QualifiedName>>> {
    match crate::v2_std_qualified_name::declaration_denotation_of_type(t) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(denotation) => match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(bindings, denotation.declaration.clone())).clone() {
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: claimants, .. } => crate::std_optional::optional_present(claimants.clone()),
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: _, .. } => crate::std_optional::optional_absent(),
    MentionDeclaringIdentity::MentionDeclaringUnavailable => crate::std_optional::optional_absent(),
},
}
}

pub fn infer_alias_body_is_phantom(aliased: Rc<Node>) -> bool {
    match infer_type_declaration_ref(aliased) {
    Some(head) => (head.clone() == crate::std_decl_ref::decl_ref("std.constructors".to_string(), "Phantom".to_string())),
    std::option::Option::None => false,
}
}

pub fn infer_type_alias_unfolded_at(t: Rc<Node>, bodies: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Option<Rc<Node>> {
    match crate::v2_std_qualified_name::declaration_denotation_of_type(t) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(denotation) => match (*crate::v2_std_symbol_index::symbol_index_declaring_path_of(bindings.clone(), denotation.declaration.clone())).clone() {
    MentionDeclaringIdentity::MentionDeclaringUnavailable => crate::std_optional::optional_absent(),
    MentionDeclaringIdentity::MentionDeclaringContested { claimants: _, .. } => crate::std_optional::optional_absent(),
    MentionDeclaringIdentity::MentionDeclaringUnique { declaring: identity, .. } => match infer_type_alias_stored_at(bindings.clone(), bodies, denotation.declaration.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(stored) => {
        let declared = infer_type_decl_identity_node(stored.clone(), identity.clone());
match (*crate::v2_std_type_binder::type_decl_view(declared.clone())).clone() {
    TypeDeclView::TypeAlias { aliased, .. } => if infer_alias_body_is_phantom(aliased.clone()) {
            crate::std_optional::optional_absent()
        } else {
            infer_type_alias_rhs(declared.clone(), aliased.clone(), denotation.type_arguments.clone())
        },
    TypeDeclView::GenericTypeDecl { .. } => crate::std_optional::optional_absent(),
    TypeDeclView::OpaqueTypeDecl { binders: _, .. } => crate::std_optional::optional_absent(),
    TypeDeclView::NotATypeDecl => crate::std_optional::optional_absent(),
    TypeDeclView::PlainTypeDecl { member: _, .. } => crate::std_optional::optional_absent(),
}
},
},
},
}
}

pub fn infer_type_alias_normalized_at(t: Rc<Node>, bodies: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Rc<Node> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match infer_kernel_value_type_optional(t.clone()) {
    Some(k) => k.clone(),
    std::option::Option::None => match infer_type_alias_unfolded_at(t.clone(), bodies.clone(), bindings.clone()) {
    Some(unfolded) => infer_type_alias_normalized_at(unfolded.clone(), bodies.clone(), bindings.clone()),
    std::option::Option::None => match (*t.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Instantiation => Rc::new(Node {
    kind: t.kind.clone(),
    children: t.children.clone().iter().cloned().fold(Rc::new(vec![]), |acc: Rc<Vec<Rc<Edge>>>, e: Rc<Edge>| crate::std_algebra::list_snoc_item(acc, Rc::new(Edge {
    label: e.label.clone(),
    target: infer_type_alias_normalized_at(e.target.clone(), bodies.clone(), bindings.clone()),
    declaration: e.declaration.clone(),
}))),
    occurrence_id: t.occurrence_id.clone(),
}),
    _ => t.clone(),
} },
    NodeKind::ComputationNode { behavior: _, .. } => t.clone(),
},
},
}
    })
}

pub fn infer_match_generic_formal_or_carrier(formal: Rc<Node>, produced: Rc<Node>, type_params: Rc<Vec<Symbol>>, instances: Rc<Vec<Rc<TypeVariableInstance>>>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Rc<InferFormalMatch> {
    match (*infer_match_generic_formal(formal.clone(), produced.clone(), type_params.clone(), instances.clone(), declarations.clone())).clone() {
    InferFormalMatch::InferFormalMatched { instances: matched, .. } => Rc::new(InferFormalMatch::InferFormalMatched {
    instances: matched.clone(),
}),
    InferFormalMatch::InferFormalShapeMismatch => match refinement_declared_carrier(declarations.clone(), produced.clone()) {
    Some(carrier) => infer_match_generic_formal(formal.clone(), infer_type_alias_normalized_at(carrier.clone(), declarations.clone(), bindings), type_params.clone(), instances.clone(), declarations.clone()),
    std::option::Option::None => Rc::new(InferFormalMatch::InferFormalShapeMismatch),
},
}
}

pub fn infer_kernel_value_type_optional(t: Rc<Node>) -> Option<Rc<Node>> {
    if crate::v2_std_node::node_equal_ignoring_provenance(t.clone(), crate::v2_std_integer::integer_int_type_node()) {
        crate::std_optional::optional_present(crate::v2_std_integer::integer_int_type_node())
    } else {
        if crate::v2_std_node::node_equal_ignoring_provenance(t.clone(), crate::v2_std_logic::bool_node()) {
            crate::std_optional::optional_present(crate::v2_std_logic::bool_node())
        } else {
            match crate::v2_std_qualified_name::declaration_denotation_of_type(t.clone()) {
    Some(denotation) => match crate::v2_extdeps_languages_dag::dag_kernel_type_declaration_binding_optional(denotation.declaration.clone()) {
    Some(binding) => crate::v2_extdeps_languages_dag::dag_binding_denotation(binding.clone()),
    std::option::Option::None => crate::std_optional::optional_absent(),
},
    std::option::Option::None => match crate::v2_std_grammar::node_atom_identity_optional(t.clone()) {
    Some(id) => crate::v2_extdeps_languages_dag::dag_binding_denotation(id.clone()),
    std::option::Option::None => crate::std_optional::optional_absent(),
},
}
        }
    }
}

pub fn infer_declared_type_obligation(position: Rc<DeclaredTypePosition>, parameter_identity: std::string::String, declared: Rc<Node>, produced: Rc<Node>, application: Rc<Node>, type_variables: Rc<Vec<Symbol>>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Rc<DeclaredTypeObligation> {
    Rc::new(DeclaredTypeObligation {
    position: position.clone(),
    parameter_identity: parameter_identity.clone(),
    declared: infer_type_alias_normalized_at(declared, declarations.clone(), bindings.clone()),
    produced: infer_type_alias_normalized_at(produced.clone(), declarations.clone(), bindings.clone()),
    produced_declared_carrier: match refinement_declared_carrier(declarations.clone(), produced.clone()) {
    Some(c) => Some(infer_type_alias_normalized_at(c.clone(), declarations.clone(), bindings.clone())),
    std::option::Option::None => std::option::Option::None,
},
    application: application.clone(),
    type_variables: type_variables.clone(),
})
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum InferLiteralElaboration {
    InferLiteralElaboratesTo {
        destination_type: Rc<Node>,
    },
    InferLiteralNotElaborated,
    InferLiteralElaborationRefused {
        cause: Symbol,
    },
}

pub fn infer_type_declaration_ref(t: Rc<Node>) -> Option<Rc<DeclarationRef>> {
    match crate::v2_std_qualified_name::declaration_denotation_of_type(t) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(denotation) => match crate::v2_std_qualified_name::qualified_name_last_segment(denotation.declaration.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(leaf) => crate::std_optional::optional_present(crate::std_decl_ref::decl_ref(crate::v2_std_qualified_name::qualified_name_to_dotted_string(crate::v2_std_qualified_name::qualified_name_init(denotation.declaration.clone())), v1_rt::symbol_lexeme(leaf.clone()))),
},
}
}

pub fn infer_negated_int_literal_value(node: Rc<Node>) -> Option<i64> {
    match (*node.kind.clone()).clone() {
    NodeKind::ComputationNode { behavior: Behavior::Transform, .. } => {
        let targets = crate::v2_std_node::positional_child_target_nodes(node.clone());
if (crate::std_algebra::length(targets.clone()) != 2) {
            crate::std_optional::optional_absent()
        } else {
            match v1_rt::list_get_optional(&targets, 0) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(op) => if (infer_operator_is_minus_token(op.clone()) || crate::v2_std_compilers_target_model::canonical_operation_wire_matches_operation(op.clone(), crate::v2_std_compilers_target_model::canonical_operation_op_sub())) {
                match v1_rt::list_get_optional(&targets, 1) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(operand) => match (*crate::v2_extdeps_languages_dag::dag_canonical_literal_from_node(operand.clone())).clone() {
    Outcome::Accepted { value: ref __rc_value, .. } => { match __rc_value.as_ref() {
    DagCanonicalLiteral::DagCanonicalIntLiteral { magnitude: m, .. } => crate::std_optional::optional_present(v1_rt::int_sub(0, m.clone())),
    _ => crate::std_optional::optional_absent(),
} },
    Outcome::Rejected { diagnostics: _, .. } => crate::std_optional::optional_absent(),
},
}
            } else {
                crate::std_optional::optional_absent()
            },
}
        }
},
    NodeKind::ComputationNode { behavior: _, .. } => crate::std_optional::optional_absent(),
    NodeKind::TypeNode { connective: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn infer_operator_is_minus_token(op_node: Rc<Node>) -> bool {
    match crate::v2_std_grammar::node_atom_identity_optional(op_node) {
    Some(id) => (id.clone() == "dag_token_minus".to_string()),
    std::option::Option::None => false,
}
}

pub fn infer_literal_elaboration_refusal_reason(cause: Rc<LiteralElaborationRefusal>) -> std::string::String {
    match (*cause.clone()).clone() {
    LiteralElaborationRefusal::HomomorphismDuplicated { .. } => "infer_reason_literal_homomorphism_duplicated".to_string(),
}
}

pub fn infer_literal_elaborates_at(literal_node: Rc<Node>, expected: Rc<Node>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Rc<InferLiteralElaboration> {
    if (infer_node_is_literal(literal_node.clone()) && infer_expected_is_optional(expected.clone(), declarations.clone(), bindings.clone())) {
        Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: "infer_literal_at_optional_is_not_present".to_string(),
})
    } else {
        infer_literal_elaborates_at_declared(literal_node.clone(), expected.clone(), declarations.clone(), bindings.clone())
    }
}

pub fn infer_node_is_literal(node: Rc<Node>) -> bool {
    match (*crate::v2_extdeps_languages_dag::dag_canonical_literal_from_node(node.clone())).clone() {
    Outcome::Accepted { .. } => true,
    Outcome::Rejected { diagnostics: _, .. } => match infer_negated_int_literal_value(node.clone()) {
    Some(_) => true,
    std::option::Option::None => false,
},
}
}

pub fn infer_expected_is_optional(expected: Rc<Node>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> bool {
    match crate::v2_std_qualified_name::declaration_denotation_of_type(infer_type_alias_normalized_at(expected, declarations, bindings)) {
    std::option::Option::None => false,
    Some(denotation) => crate::v2_std_qualified_name::declaration_denotation_is_optional(denotation.clone()),
}
}

pub fn infer_literal_elaborates_at_declared(literal_node: Rc<Node>, expected: Rc<Node>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Rc<InferLiteralElaboration> {
    match (*crate::v2_extdeps_languages_dag::dag_canonical_literal_from_node(literal_node.clone())).clone() {
    Outcome::Rejected { diagnostics: _, .. } => match infer_negated_int_literal_value(literal_node.clone()) {
    std::option::Option::None => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    Some(v) => infer_int_literal_value_at(v.clone(), expected.clone(), declarations.clone(), bindings.clone()),
},
    Outcome::Accepted { value: literal, .. } => match (*literal.clone()).clone() {
    DagCanonicalLiteral::DagCanonicalIntLiteral { magnitude: m, .. } => infer_int_literal_value_at(m.clone(), expected.clone(), declarations.clone(), bindings.clone()),
    DagCanonicalLiteral::DagCanonicalBoolLiteral { value: _, .. } => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    DagCanonicalLiteral::DagCanonicalSymbolLiteral { symbol: _, .. } => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    DagCanonicalLiteral::DagCanonicalStringLiteral { value: _, .. } => infer_string_literal_at(expected.clone(), declarations.clone(), bindings.clone()),
    DagCanonicalLiteral::DagCanonicalFloatLiteral { lexeme: _, .. } => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
},
}
}

pub fn infer_string_literal_at(expected: Rc<Node>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Rc<InferLiteralElaboration> {
    {
        let wanted = infer_type_alias_normalized_at(expected, declarations, bindings);
match infer_type_declaration_ref(wanted.clone()) {
    std::option::Option::None => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    Some(destination) => match crate::v2_std_qualified_name::declaration_denotation_of_type(wanted.clone()) {
    std::option::Option::None => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    Some(denotation) => { let __fm = denotation.type_arguments.clone(); if __fm.len() == 1 { let element_type = (*__fm)[0].clone(); match infer_type_declaration_ref(element_type.clone()) {
    std::option::Option::None => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    Some(element) => match (*crate::std_literal_elaboration::elaborate_literal_at(literal_homomorphism_rows(), LiteralSourceKind::KernelStringLiteral, destination.clone(), crate::std_optional::optional_present(element.clone()), false)).clone() {
    LiteralElaborationOutcome::ViaHomomorphism { homomorphism: _, .. } => Rc::new(InferLiteralElaboration::InferLiteralElaboratesTo {
    destination_type: wanted.clone(),
}),
    LiteralElaborationOutcome::DirectLiteral => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    LiteralElaborationOutcome::LiteralElaborationRefused { cause: c, .. } => Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: infer_literal_elaboration_refusal_reason(c.clone()),
}),
},
} } else if __fm.len() >= 1 { Rc::new(InferLiteralElaboration::InferLiteralNotElaborated) } else { Rc::new(InferLiteralElaboration::InferLiteralNotElaborated) } },
},
}
}
}

pub fn infer_int_literal_value_at(value: i64, expected: Rc<Node>, declarations: Rc<SymbolIndex>, bindings: Rc<SymbolIndex>) -> Rc<InferLiteralElaboration> {
    {
        let wanted = infer_type_alias_normalized_at(expected, declarations, bindings);
match infer_type_declaration_ref(wanted.clone()) {
    std::option::Option::None => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    Some(destination) => match (*infer_machine_width_of(wanted.clone())).clone() {
    InferMachineWidth::WidthReadable { signedness, bits, .. } => if crate::std_machine_width_range::machine_width_admits(signedness.clone(), bits.clone(), value.clone()) {
            Rc::new(InferLiteralElaboration::InferLiteralElaboratesTo {
    destination_type: wanted.clone(),
})
        } else {
            Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: "infer_reason_literal_outside_machine_width".to_string(),
})
        },
    InferMachineWidth::WidthUnreadable { reason: r, .. } => Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: r.clone(),
}),
    InferMachineWidth::NotWidthConstrained => infer_int_literal_value_at_declared(value.clone(), wanted.clone(), destination.clone()),
},
}
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum InferMachineWidth {
    NotWidthConstrained,
    WidthReadable {
        signedness: Signedness,
        bits: BitWidth,
    },
    WidthUnreadable {
        reason: Symbol,
    },
}

pub fn infer_machine_width_of(t: Rc<Node>) -> Rc<InferMachineWidth> {
    match infer_type_declaration_ref(t.clone()) {
    std::option::Option::None => Rc::new(InferMachineWidth::NotWidthConstrained),
    Some(head) => if (head.clone() == crate::std_decl_ref::decl_ref("std.machine_constraints".to_string(), "Compose".to_string())) {
        { let __fm = infer_type_head_and_args(t.clone()).args.clone(); if __fm.len() == 2 { let carrier = (*__fm)[0].clone(); let width = (*__fm)[1].clone(); if infer_type_names_machine_width(width.clone()) {
            match infer_machine_width_bits(width.clone()) {
    std::option::Option::None => Rc::new(InferMachineWidth::WidthUnreadable {
    reason: "infer_reason_machine_width_not_static".to_string(),
}),
    Some(bits) => match infer_machine_width_signedness(carrier.clone()) {
    std::option::Option::None => Rc::new(InferMachineWidth::WidthUnreadable {
    reason: "infer_reason_machine_width_carrier_signedness_undeclared".to_string(),
}),
    Some(signedness) => Rc::new(InferMachineWidth::WidthReadable {
    signedness: signedness.clone(),
    bits: bits.clone(),
}),
},
}
        } else {
            Rc::new(InferMachineWidth::NotWidthConstrained)
        } } else if __fm.len() >= 1 { Rc::new(InferMachineWidth::WidthUnreadable {
    reason: "infer_reason_machine_width_compose_malformed".to_string(),
}) } else { Rc::new(InferMachineWidth::WidthUnreadable {
    reason: "infer_reason_machine_width_compose_malformed".to_string(),
}) } }
    } else {
        Rc::new(InferMachineWidth::NotWidthConstrained)
    },
}
}

pub fn infer_type_names_machine_width(t: Rc<Node>) -> bool {
    match infer_type_declaration_ref(t) {
    std::option::Option::None => false,
    Some(head) => (head.clone() == crate::std_decl_ref::decl_ref("std.machine_constraints".to_string(), "MachineWidth".to_string())),
}
}

pub fn infer_machine_width_bits(t: Rc<Node>) -> Option<BitWidth> {
    { let __fm = infer_type_head_and_args(t).args.clone(); if __fm.len() == 1 { let literal = (*__fm)[0].clone(); match (*crate::v2_extdeps_languages_dag::dag_int_literal_magnitude_int_from_node(literal.clone())).clone() {
    Outcome::Accepted { value: m, .. } => crate::std_optional::optional_present(crate::std_measure::bit_width(crate::std_checked_arithmetic::nat_magnitude(m.clone()))),
    Outcome::Rejected { diagnostics: _, .. } => crate::std_optional::optional_absent(),
} } else if __fm.len() >= 1 { crate::std_optional::optional_absent() } else { crate::std_optional::optional_absent() } }
}

pub fn infer_machine_width_signedness(carrier: Rc<Node>) -> Option<Signedness> {
    if crate::v2_std_node::node_equal_ignoring_provenance(carrier.clone(), crate::v2_std_integer::integer_int_type_node()) {
        crate::std_optional::optional_present(Signedness::Signed)
    } else {
        match infer_type_declaration_ref(carrier.clone()) {
    Some(d) => if (d.clone() == crate::std_decl_ref::decl_ref("std.nat".to_string(), "Nat".to_string())) {
            crate::std_optional::optional_present(Signedness::Unsigned)
        } else {
            crate::std_optional::optional_absent()
        },
    std::option::Option::None => crate::std_optional::optional_absent(),
}
    }
}

pub fn infer_int_literal_value_at_declared(value: i64, wanted: Rc<Node>, destination: Rc<DeclarationRef>) -> Rc<InferLiteralElaboration> {
    match (*crate::std_literal_elaboration::kernel_grounding_for(kernel_grounding_rows(), LiteralSourceKind::KernelIntLiteral, destination.clone())).clone() {
    KernelGroundingLookup::KernelGroundingFound { row: row, .. } => if crate::std_literal_elaboration::kernel_grounding_admits(row.clone(), value.clone()) {
        Rc::new(InferLiteralElaboration::InferLiteralElaboratesTo {
    destination_type: wanted.clone(),
})
    } else {
        Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: "infer_reason_literal_outside_kernel_grounding_range".to_string(),
})
    },
    KernelGroundingLookup::KernelGroundingAmbiguous { row_count: _, .. } => Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: "infer_reason_kernel_grounding_duplicated".to_string(),
}),
    KernelGroundingLookup::KernelGroundingAbsent => match (*crate::std_literal_elaboration::elaborate_literal_at(literal_homomorphism_rows(), LiteralSourceKind::KernelIntLiteral, destination.clone(), std::option::Option::None, false)).clone() {
    LiteralElaborationOutcome::ViaHomomorphism { homomorphism: _, .. } => if (value.clone() < 0) {
        Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: "infer_reason_negative_literal_has_no_image_in_destination".to_string(),
})
    } else {
        Rc::new(InferLiteralElaboration::InferLiteralElaboratesTo {
    destination_type: wanted.clone(),
})
    },
    LiteralElaborationOutcome::DirectLiteral => Rc::new(InferLiteralElaboration::InferLiteralNotElaborated),
    LiteralElaborationOutcome::LiteralElaborationRefused { cause: c, .. } => Rc::new(InferLiteralElaboration::InferLiteralElaborationRefused {
    cause: infer_literal_elaboration_refusal_reason(c.clone()),
}),
},
}
}

