pub fn infer_transform_is_unary_prefix_algebra_shape(node: Rc<Node>) -> bool {
    {
        let positional_targets = crate::v2_std_node::positional_child_target_nodes(node.clone());
if (!crate::v2_std_node::all_edges_positional(node.children.clone()) || (crate::std_algebra::length(positional_targets.clone()) != 2)) {
            false
        } else {
            match v1_rt::list_get_optional(&positional_targets, 0) {
    std::option::Option::None => false,
    Some(op_target) => match infer_operator_algebra_field(op_target.clone()) {
    Some(_) => true,
    std::option::Option::None => false,
},
}
        }
}
}

pub fn infer_transform_unary_prefix(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>) -> Rc<Outcome<Rc<InferredFacts>>> {
    {
        let positional_targets = crate::v2_std_node::positional_child_target_nodes(node.clone());
match v1_rt::list_get_optional(&positional_targets, 0) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_transform_shape_invalid_diagnostic(node.clone())),
    Some(op_target) => match v1_rt::list_get_optional(&positional_targets, 1) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_transform_shape_invalid_diagnostic(node.clone())),
    Some(operand_target) => match infer_operator_algebra_field(op_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_transform_operator_unsupported_diagnostic(node.clone())),
    Some(field) => match lookup_inferred_facts_in_entries(entries.clone(), operand_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(operand_target.clone())),
    Some(operand_facts) => match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_branch_operand_resolved_type_with_entries(operand_target.clone(), operand_facts.clone(), entries.clone(), infer_no_type_variable_instances(), resolved)).clone() {
    Witness::Violates { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    Witness::Holds { value: operand_type, .. } => match (*infer_algebra_field_result_type(crate::v2_extdeps_languages_dag::dag_algebra_inhabitance_decls(), operand_type.clone(), field.clone(), 1)).clone() {
    InferAlgebraFieldResult::AlgebraFieldNotCarried => crate::v2_std_diagnostic::outcome_rejected(infer_transform_operand_type_mismatch_diagnostic(node.clone())),
    InferAlgebraFieldResult::AlgebraFieldRowMalformed { cause: cause, .. } => crate::v2_std_diagnostic::outcome_rejected(Rc::new(Diagnostic {
    reason: cause.clone(),
    at: crate::v2_std_diagnostic::node_locus(node.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})),
    InferAlgebraFieldResult::AlgebraFieldResultType { result: answer, .. } => match (*infer_operation_value_type(op_target.clone(), answer.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: result_type, .. } => match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome(inferred_facts_from_derived_type(node.clone(), result_type.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), |facts| Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(cd.clone()),
})),
},
},
},
} },
},
},
},
},
}
}
}

pub fn infer_transform_binary_infix(node: Rc<Node>, partials: Rc<Vec<Rc<Node>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, resolved: Rc<ResolvedTree>) -> Rc<Outcome<Rc<InferredFacts>>> {
    {
        let positional_targets = crate::v2_std_node::positional_child_target_nodes(node.clone());
if (!crate::v2_std_node::all_edges_positional(node.children.clone()) || (crate::std_algebra::length(positional_targets.clone()) != 3)) {
            crate::v2_std_diagnostic::outcome_rejected(infer_transform_shape_invalid_diagnostic(node.clone()))
        } else {
            match v1_rt::list_get_optional(&positional_targets, 0) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_transform_shape_invalid_diagnostic(node.clone())),
    Some(op_target) => match v1_rt::list_get_optional(&positional_targets, 1) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_transform_shape_invalid_diagnostic(node.clone())),
    Some(left_target) => match v1_rt::list_get_optional(&positional_targets, 2) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_transform_shape_invalid_diagnostic(node.clone())),
    Some(right_target) => match infer_operator_algebra_field(op_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_transform_operator_unsupported_diagnostic(node.clone())),
    Some(field) => match lookup_inferred_facts_in_entries(entries.clone(), left_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(left_target.clone())),
    Some(left_facts) => match lookup_inferred_facts_in_entries(entries.clone(), right_target.clone()) {
    std::option::Option::None => crate::v2_std_diagnostic::outcome_rejected(infer_facts_lookup_miss_diagnostic(right_target.clone())),
    Some(right_facts) => match (*crate::v2_std_bounded_lattice_completeness::infer_bounded_lattice_consumer_gate(node.clone(), partials)).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { diagnostics: ref __rc_diagnostics, .. } => { let cd = __rc_diagnostics.as_ref(); match (*infer_unify_transform_operand_types(left_target.clone(), left_facts.clone(), right_target.clone(), right_facts.clone(), entries.clone(), resolved)).clone() {
    InferOperandJudgment::OperandsDisagree { diagnostic: d, .. } => crate::v2_std_diagnostic::outcome_rejected(d.clone()),
    InferOperandJudgment::OperandsNotJudged { diagnostic: d, .. } => if infer_field_is_comparison(field.clone()) {
                infer_comparison_not_derived(node.clone(), cd.clone())
            } else {
                crate::v2_std_diagnostic::outcome_rejected(d.clone())
            },
    InferOperandJudgment::OperandsOneType { operand_type: unified_type, .. } => match (*infer_algebra_field_result_type(crate::v2_extdeps_languages_dag::dag_algebra_inhabitance_decls(), unified_type.clone(), field.clone(), 2)).clone() {
    InferAlgebraFieldResult::AlgebraFieldNotCarried => if infer_field_is_comparison(field.clone()) {
                infer_comparison_not_derived(node.clone(), cd.clone())
            } else {
                crate::v2_std_diagnostic::outcome_rejected(infer_transform_operand_type_mismatch_diagnostic(node.clone()))
            },
    InferAlgebraFieldResult::AlgebraFieldRowMalformed { cause: cause, .. } => crate::v2_std_diagnostic::outcome_rejected(Rc::new(Diagnostic {
    reason: cause.clone(),
    at: crate::v2_std_diagnostic::node_locus(node.clone()),
    correction: Rc::new(Correction::Unavailable {
    reason: Rc::new(NoCorrectionReason::CorrectionNotModeled),
}),
})),
    InferAlgebraFieldResult::AlgebraFieldResultType { result: answer, .. } => match (*infer_operation_value_type(op_target.clone(), answer.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => Rc::new(Outcome::Rejected {
    diagnostics: r.clone(),
}),
    Outcome::Accepted { value: result_type, .. } => match (*infer_descent_witness_for_node(node.clone())).clone() {
    Witness::Violates { diagnostic: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(d.clone()),
}),
    Witness::Holds { value: descent_proof, .. } => crate::v2_std_diagnostic::bind_outcome(inferred_facts_from_derived_type(node.clone(), result_type.clone(), Rc::new(Witness::<Rc<TerminationProof>>::Holds {
    value: descent_proof.clone(),
})), |facts| Rc::new(Outcome::Accepted {
    value: facts.clone(),
    diagnostics: Box::new(cd.clone()),
})),
},
},
},
} },
},
},
},
},
},
},
}
        }
}
}

