pub fn infer_gather_acc_to_outcome(acc: Rc<InferGatherFoldAcc>) -> Rc<Outcome<Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>>> {
    if acc.failed.clone() {
        match (*acc.pending).clone() {
    std::option::Option::None => Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(infer_canonical_grounding_incoherent_diagnostic(infer_gather_fold_failure_node())),
}),
    Some(nds) => Rc::new(Outcome::Rejected {
    diagnostics: nds.clone(),
}),
}
    } else {
        Rc::new(Outcome::Accepted {
    value: acc.entries.clone(),
    diagnostics: Box::new((*acc.pending).clone()),
})
    }
}

