pub fn infer_gather_formed_facts_row(node: Rc<Node>, formed: Rc<Outcome<Rc<InferredFacts>>>, entries: Rc<HashMap<Rc<Node>, Rc<Vec<Rc<InferredFacts>>>>>, pending: Option<Rc<NonEmptyDiagnostics>>) -> Rc<InferGatherFoldAcc> {
    match (*formed.clone()).clone() {
    Outcome::Rejected { diagnostics: r, .. } => infer_gather_fold_acc_failed(node.clone(), crate::v2_std_diagnostic::rejected_with_pending(pending.clone(), r.clone()), false, false, false, false, 0),
    Outcome::Accepted { value: facts, diagnostics: ref __rc_diagnostics, .. } => { let d = __rc_diagnostics.as_ref(); match (*admitted_inferred_facts_entry(node.clone(), facts.clone())).clone() {
    Outcome::Rejected { diagnostics: r, .. } => infer_gather_fold_acc_failed(node.clone(), crate::v2_std_diagnostic::rejected_with_pending(pending.clone(), r.clone()), false, false, false, false, 0),
    Outcome::Accepted { value: entry, diagnostics: ref __rc_diagnostics, .. } => { let ed = __rc_diagnostics.as_ref(); infer_gather_fold_acc_ok(node.clone(), inferred_facts_index_enter(entries, entry.clone()), crate::v2_std_diagnostic::diagnostics_merge(crate::v2_std_diagnostic::diagnostics_merge(pending.clone(), d.clone()), ed.clone()), false, false, false, false, 0) },
} },
}
}

pub fn infer_sum_nullary_payload_edge(parent: Rc<Node>, edge: Rc<Edge>) -> bool {
    match (*parent.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } if matches!(__rc_connective.as_ref(), Connective::Disj) => { let Connective::Disj = __rc_connective.as_ref() else { unreachable!() }; (match (*edge.label.clone()).clone() {
    EdgeLabel::StructuralLabel { label: _, .. } => false,
    EdgeLabel::Authored { name: _, .. } => true,
    EdgeLabel::Positional => false,
} && infer_empty_product_shape(edge.target.clone())) },
    _ => false,
}
}

